1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// 数据目录布局：
16	//
17	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
18	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
19	//
20	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
21	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
22	
23	const stateVersion = 1
24	
25	type customer struct {
26		ID     string `json:"id"`
27		Name   string `json:"name"`
28		Price  int64  `json:"price_fen"`         // 固定单价，非负整数分，创建后不可修改
29		PlanID string `json:"plan_id,omitempty"` // 绑定的阶梯计费方案标识；空表示固定单价客户，创建后不可变更
30	}
31	
32	// tier 是阶梯计费方案中的一档：Limit 为月累计数量上限（正整数），
33	// 仅最后一档无上限（Limit 为 0）；Price 为该档每单位价格（非负整数分）。
34	type tier struct {
35		Limit int64 `json:"limit"`     // 累计数量上限；0 表示无上限（仅最后一档）
36		Price int64 `json:"price_fen"` // 每单位价格，非负整数分，可升可降
37	}
38	
39	// plan 是按月累计用量的阶梯计费方案：标识唯一非空、名称非空、固定月费
40	// （非负整数分，省略视为 0）与至少一档有序阶梯；月费与规则创建后不可修改。
41	type plan struct {
42		ID         string `json:"id"`
43		Name       string `json:"name"`
44		MonthlyFee int64  `json:"monthly_fee_fen,omitempty"` // 固定月费，非负整数分；每账期收取一次整月，不按天折算
45		Tiers      []tier `json:"tiers"`                     // 至少一档；有限上限严格递增，最后一档无上限
46	}
47	
48	type usageRecord struct {
49		ID         string `json:"id"`
50		CustomerID string `json:"customer_id"`
51		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
52		Quantity   int64  `json:"quantity"`
53	}
54	
55	// lineSegment 是阶梯计费下一条用量记录落入某一档的分段：数量与小计；
56	// 该档单价由账单保存的方案规则按档位序号取得。
57	type lineSegment struct {
58		Tier     int   `json:"tier"`     // 档位序号（0 起，对应账单保存的方案规则）
59		Quantity int64 `json:"quantity"` // 落入本档的数量
60		Fee      int64 `json:"fee_fen"`  // 本分段小计（数量 × 该档单价）
61	}
62	
63	// tierTotal 是阶梯账单中某一档的合计数量与金额（与 PlanTiers 顺序对齐）。
64	type tierTotal struct {
65		Quantity int64 `json:"quantity"`
66		Fee      int64 `json:"fee_fen"`
67	}
68	
69	type billLine struct {
70		UsageID  string        `json:"usage_id"`
71		Time     string        `json:"time"`
72		Quantity int64         `json:"quantity"`
73		LineFee  int64         `json:"line_fee_fen"`
74		Segments []lineSegment `json:"segments,omitempty"` // 阶梯账单：本条用量的跨档分段
75	}
76	
77	type bill struct {
78		ID         string      `json:"id"`
79		CustomerID string      `json:"customer_id"`
80		Month      string      `json:"month"`                 // YYYY-MM（UTC）
81		Pricing    string      `json:"pricing,omitempty"`     // 计价类型：空或 fixed 为固定单价；tiered 为阶梯计费
82		PlanID     string      `json:"plan_id,omitempty"`     // 阶梯账单：方案标识
83		PlanName   string      `json:"plan_name,omitempty"`   // 阶梯账单：方案名称（快照）
84		PlanTiers  []tier      `json:"plan_tiers,omitempty"`  // 阶梯账单：完整方案规则（快照）
85		TierTotals []tierTotal `json:"tier_totals,omitempty"` // 阶梯账单：各档实际数量与金额合计
86		// 阶梯账单：实际收取的固定月费快照（分），非负；按账期有效方案收取一次
87		// 整月，不计入总数量、各档金额或逐条小计。固定单价账单恒为 0。
88		MonthlyFee int64      `json:"monthly_fee_fen,omitempty"`
89		TotalQty   int64      `json:"total_quantity"`
90		UnitPrice  int64      `json:"unit_price_fen"` // 固定单价账单的单价；阶梯账单恒为 0（不伪造统一单价）
91		TotalFee   int64      `json:"total_fee_fen"`
92		Lines      []billLine `json:"lines"`
93		CreatedAt  string     `json:"created_at"`
94	}
95	
96	// adjustment 是对已结算账单的一次费用调整（正数补收、负数减免）。
97	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录。
98	type adjustment struct {
99		ID           string `json:"id"`
100		CustomerID   string `json:"customer_id"`
101		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
102		Amount       int64  `json:"amount_fen"`
103		Reason       string `json:"reason"`
104		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
105		CreatedAt    string `json:"created_at"`
106		Revoked      bool   `json:"revoked"`
107		RevokeReason string `json:"revoke_reason,omitempty"`
108		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
109		RevokedAt    string `json:"revoked_at,omitempty"`
110	}
111	
112	// paymentAllocation 是一笔收款在某个已结算月份上的分配（正整数分）。
113	type paymentAllocation struct {
114		Month  string `json:"month"`      // YYYY-MM（UTC），须已有账单
115		Amount int64  `json:"amount_fen"` // 正整数分
116	}
117	
118	// payment 是一笔实收登记：同一客户的一笔汇款（总额 Total 分）按分配列表
119	// 计入一个或多个已结算月份；单账单收款视为只有一项分配的汇款。
120	// 记录一旦写入永不删除；撤销只是追加撤销信息，整笔撤销全部分配并保留
121	// 原记录，撤销后该笔不再计入实收，也不会因重放而恢复。
122	type payment struct {
123		ID          string              `json:"id"`
124		CustomerID  string              `json:"customer_id"`
125		Total       int64               `json:"total_fen"` // 收款总额，正整数分，等于分配合计
126		Note        string              `json:"note"`
127		Allocations []paymentAllocation `json:"allocations"` // 至少一项，月份不重复，按月份升序保存
128		// Auto 为 true 表示该收款由 bill remit-auto 自动分配登记：首次分配由工具
129		// 按最早欠款账期确定，判重只看客户、总额与备注；false（含旧存档缺字段）
130		// 表示 bill pay / bill remit 的显式分配登记，仍按月份-金额对应关系判重。
131		// 自动与显式分配登记之间不得复用同一收款标识。
132		Auto         bool   `json:"auto,omitempty"`
133		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
134		CreatedAt    string `json:"created_at"`
135		Revoked      bool   `json:"revoked"`
136		RevokeReason string `json:"revoke_reason,omitempty"`
137		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
138		RevokedAt    string `json:"revoked_at,omitempty"`
139	}
140	
141	// UnmarshalJSON 兼容旧版单账单收款格式（month + amount_fen，无 allocations）：
142	// 读入时归一化为一项分配，之后一律按新格式写回。
143	func (p *payment) UnmarshalJSON(data []byte) error {
144		type plain payment // 去掉方法，避免递归
145		var raw struct {
146			plain
147			Month  string `json:"month"`      // 旧格式：所属账单月份
148			Amount int64  `json:"amount_fen"` // 旧格式：收款金额
149		}
150		if err := json.Unmarshal(data, &raw); err != nil {
151			return err
152		}
153		*p = payment(raw.plain)
154		if len(p.Allocations) == 0 && raw.Month != "" {
155			p.Allocations = []paymentAllocation{{Month: raw.Month, Amount: raw.Amount}}
156			p.Total = raw.Amount
157		}
158		return nil
159	}
160	
161	// amountFor 返回该收款在指定月份的分配金额；无分配时为 0。
162	func (p *payment) amountFor(month string) int64 {
163		for _, al := range p.Allocations {
164			if al.Month == month {
165				return al.Amount
166			}
167		}
168		return 0
169	}
170	
171	// correction 是对一笔未撤销收款的分配更正：客户、总额、备注、原账单及
172	// 应付不变，仅把该笔收款当前生效的分配整体替换为完整新分配。记录一旦写入
173	// 永不删除；首次登记内容永久保留，bill pay / bill remit 仍按原始分配判重，
174	// 更正不影响收款身份。可连续更正，每次以当时最新分配为起点。
175	type correction struct {
176		ID          string              `json:"id"`
177		PaymentID   string              `json:"payment_id"` // 目标收款标识
178		Reason      string              `json:"reason"`
179		Allocations []paymentAllocation `json:"allocations"` // 完整新分配，至少一项，月份不重复，按月份升序保存
180		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款及其撤销共用
181		CreatedAt   string              `json:"created_at"`
182	}
183	
184	// refund 是对一笔已登记收款的部分退款登记：从该收款当前最新分配涉及的
185	// 月份中实际退回资金，各月退款金额为正整数分，累计不得超过该笔在该月的
186	// 分配。记录一旦写入永不删除、不可撤销；首次退款后该收款的最新分配固定，
187	// 不得再新增分配更正或整笔撤销。退款标识与收款、调整、更正标识命名空间
188	// 相互独立，可同名。
189	type refund struct {
190		ID          string              `json:"id"`
191		PaymentID   string              `json:"payment_id"` // 目标收款标识
192		Reason      string              `json:"reason"`
193		Allocations []paymentAllocation `json:"allocations"` // 各月退款金额，至少一项，月份不重复，按月份升序保存
194		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款/更正及其撤销共用
195		CreatedAt   string              `json:"created_at"`
196	}
197	
198	// planChange 是阶梯客户的一次按月生效的方案变更：自生效月（UTC 自然月，
199	// 含）起改用目标方案，直到下一次变更；生效月之前的月份不受影响。记录一旦
200	// 写入永不修改或删除；变更不产生账后流水事件，也不占用全局操作序号。
201	type planChange struct {
202		CustomerID string `json:"customer_id"`
203		Month      string `json:"month"`   // YYYY-MM（UTC），生效月（含）
204		PlanID     string `json:"plan_id"` // 目标阶梯计费方案标识
205		Reason     string `json:"reason"`
206		CreatedAt  string `json:"created_at"`
207	}
208	
209	// suspension 是阶梯客户的一段按月暂停区间：自起月（UTC 自然月，含）起
210	// 暂停服务，直到结束月（不含），即 [StartMonth, EndMonth) 覆盖的自然月。
211	// 暂停月不接收用量、不产生月费账单；区间可相接（相接视为连续暂停）但不得
212	// 重叠。记录一旦写入永不修改或删除；暂停不产生账后流水事件，也不占用全局
213	// 操作序号。固定单价客户不适用暂停。
214	type suspension struct {
215		CustomerID string `json:"customer_id"`
216		StartMonth string `json:"start_month"` // YYYY-MM（UTC），暂停起月（含）
217		EndMonth   string `json:"end_month"`   // YYYY-MM（UTC），原结束月（不含），严格晚于起月；登记提前恢复后仍永久保留原值
218		Reason     string `json:"reason"`      // 原暂停原因，永久保留
219		CreatedAt  string `json:"created_at"`
220	}
221	
222	// suspensionResume 是一段暂停的按月提前恢复登记：目标暂停由客户与原起月
223	// 共同标识，恢复月（UTC 自然月，含）起重新提供服务，该月不再受该项暂停
224	// 限制；目标暂停的当前有效区间由 [原起月, 原结束月) 缩短为 [原起月, 恢复月)，
225	// 原区间与原原因永久保留。恢复记录一旦写入永不修改、不可撤销，每项暂停只能
226	// 登记一次提前恢复；恢复不产生账后流水事件，也不占用全局操作序号。
227	type suspensionResume struct {
228		CustomerID  string `json:"customer_id"`
229		StartMonth  string `json:"start_month"`  // 目标暂停的原起月（YYYY-MM，UTC），与客户共同标识目标暂停
230		ResumeMonth string `json:"resume_month"` // YYYY-MM（UTC），恢复月（含）；严格满足 原起月 < 恢复月 < 原结束月
231		Reason      string `json:"reason"`       // 恢复原因，非空
232		CreatedAt   string `json:"created_at"`
233	}
234	
235	// withdrawal 是一条用量记录的撤回标记：原记录（客户、时间、数量、标识）永久
236	// 保留在 Usage 中，撤回只追加状态与原因，用于纠正误导入的记录。撤回不可恢复、
237	// 标识不可复用；已撤回用量不参与结算、方案变更预检与暂停区间冲突检查，但相同
238	// 内容的重放仍按原记录判重跳过。撤回只作用于该条记录，不占用全局操作序号。
239	type withdrawal struct {
240		UsageID   string `json:"usage_id"` // 撤回的用量标识（与键一致）
241		Reason    string `json:"reason"`   // 撤回原因，非空
242		CreatedAt string `json:"created_at"`
243	}
244	
245	// usageCorrection 是一条未封账用量的原子更正：以原用量标识为键，把错误的
246	// 客户、时间或数量替换为一条全新替代记录。更正成功时原记录按更正原因登记
247	// 撤回（Withdrawals 中保存同因撤回标记），替代记录登记到 Usage 并在此永久
248	// 保存关联；原内容不可改写，更正不可撤销，不占用账后操作序号。每条原用量
249	// 只能更正一次；替代记录本身仍可继续更正（形成前身→后继链）或按原规则撤回。
250	// 字段保存首次更正请求的完整内容，用于相同请求的幂等重放判定（时间按解析后
251	// 的瞬间比较）。
252	type usageCorrection struct {
253		UsageID       string `json:"usage_id"`       // 原用量标识（与键一致）
254		ReplacementID string `json:"replacement_id"` // 替代用量标识（全局唯一，首次更正时全新）
255		NewCustomerID string `json:"new_customer_id"`
256		NewTime       string `json:"new_time"` // RFC3339，保留首次更正的原始输入
257		NewQuantity   int64  `json:"new_quantity"`
258		Reason        string `json:"reason"` // 更正原因，同时是原记录的撤回原因，非空
259		CreatedAt     string `json:"created_at"`
260	}
261	
262	type state struct {
263		Version     int                     `json:"version"`
264		Customers   map[string]*customer    `json:"customers"`
265		Plans       map[string]*plan        `json:"plans"`                 // 全局唯一方案标识 -> 阶梯计费方案
266		Usage       map[string]*usageRecord `json:"usage"`                 // 全局唯一用量标识 -> 记录
267		Bills       map[string]*bill        `json:"bills"`                 // 客户 + "|" + 月份 -> 账单
268		Adjustments map[string]*adjustment  `json:"adjustments"`           // 全局唯一调整标识 -> 记录
269		Payments    map[string]*payment     `json:"payments"`              // 全局唯一收款标识 -> 记录（与调整标识相互独立，可同名）
270		Corrections map[string]*correction  `json:"corrections"`           // 全局唯一更正标识 -> 记录（与收款、调整标识相互独立，可同名）
271		Refunds     map[string]*refund      `json:"refunds,omitempty"`     // 全局唯一退款标识 -> 记录（与收款、调整、更正标识相互独立，可同名；不可撤销）
272		PlanChanges map[string]*planChange  `json:"plan_changes"`          // 客户 + "|" + 生效月 -> 方案变更（按生效月递增追加，不可改写）
273		Suspensions map[string]*suspension  `json:"suspensions,omitempty"` // 客户 + "|" + 起月 -> 暂停区间（原区间与原因不可改写）
274		// SuspensionResumes 以客户与原起月为键保存暂停的提前恢复登记；旧存档
275		// 缺少本字段时暂停沿用原区间。恢复记录永久保留、不可改写或撤销。
276		SuspensionResumes map[string]*suspensionResume `json:"suspension_resumes,omitempty"`
277		Withdrawals       map[string]*withdrawal       `json:"withdrawals,omitempty"` // 用量标识 -> 撤回标记（不可恢复，标识不可复用）
278		// UsageCorrections 以原用量标识为键保存用量更正关联；原记录同时在
279		// Withdrawals 中按更正原因标记撤回。旧存档缺少本字段视为无更正。
280		UsageCorrections map[string]*usageCorrection `json:"usage_corrections,omitempty"`
281		NextSeq          int64                       `json:"next_seq"` // 已分配的最大操作序号（调整/收款/更正/退款及其撤销共用；方案变更、暂停、用量撤回与用量更正不占用）
282		path             string                      `json:"-"`
283	}
284	
285	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
286	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
287	func loadStore(dir string) (*state, error) {
288		p := filepath.Join(dir, "state.json")
289		data, err := os.ReadFile(p)
290		if err != nil {
291			if errors.Is(err, os.ErrNotExist) {
292				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
293					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
294				}
295				return newState(p), nil
296			}
297			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
298		}
299	
300		var s state
301		dec := json.NewDecoder(bytes.NewReader(data))
302		if err := dec.Decode(&s); err != nil {
303			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
304		}
305		// 拒绝完整 JSON 之后的任何非空白内容（包括单独的 ] 或 }），避免静默
306		// 吞掉异常数据；合法尾随空白仍可读取。
307		if off := dec.InputOffset(); off < int64(len(data)) {
308			if strings.TrimSpace(string(data[off:])) != "" {
309				return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
310			}
311		}
312		if err := s.validate(); err != nil {
313			return nil, fmt.Errorf("数据文件已损坏: %w", err)
314		}
315		// 旧版本数据文件没有 plans/adjustments/payments/corrections/refunds/
316		// plan_changes/suspensions/withdrawals/usage_corrections/next_seq 字段：
317		// 视为零方案、零调整、零实收、零更正、零退款、零方案变更、零暂停、
318		// 零撤回、零用量更正（全部用量有效）。
319		if s.Plans == nil {
320			s.Plans = map[string]*plan{}
321		}
322		if s.Adjustments == nil {
323			s.Adjustments = map[string]*adjustment{}
324		}
325		if s.Payments == nil {
326			s.Payments = map[string]*payment{}
327		}
328		if s.Corrections == nil {
329			s.Corrections = map[string]*correction{}
330		}
331		if s.Refunds == nil {
332			s.Refunds = map[string]*refund{}
333		}
334		if s.PlanChanges == nil {
335			s.PlanChanges = map[string]*planChange{}
336		}
337		if s.Suspensions == nil {
338			s.Suspensions = map[string]*suspension{}
339		}
340		if s.SuspensionResumes == nil {
341			s.SuspensionResumes = map[string]*suspensionResume{}
342		}
343		if s.Withdrawals == nil {
344			s.Withdrawals = map[string]*withdrawal{}
345		}
346		if s.UsageCorrections == nil {
347			s.UsageCorrections = map[string]*usageCorrection{}
348		}
349		s.path = p
350		return &s, nil
351	}
352	
353	func newState(p string) *state {
354		return &state{
355			Version:           stateVersion,
356			Customers:         map[string]*customer{},
357			Plans:             map[string]*plan{},
358			Usage:             map[string]*usageRecord{},
359			Bills:             map[string]*bill{},
360			Adjustments:       map[string]*adjustment{},
361			Payments:          map[string]*payment{},
362			Corrections:       map[string]*correction{},
363			Refunds:           map[string]*refund{},
364			PlanChanges:       map[string]*planChange{},
365			Suspensions:       map[string]*suspension{},
366			SuspensionResumes: map[string]*suspensionResume{},
367			Withdrawals:       map[string]*withdrawal{},
368			UsageCorrections:  map[string]*usageCorrection{},
369			path:              p,
370		}
371	}
372	
373	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
374	func (s *state) validate() error {
375		if s.Version != stateVersion {
376			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
377		}
378		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
379			return errors.New("缺少必要的数据节")
380		}
381		for id, p := range s.Plans {
382			if p == nil {
383				return fmt.Errorf("方案 %q 的数据为空", id)
384			}
385			if p.ID != id {
386				return fmt.Errorf("方案标识不一致: 键 %q / 记录 %q", id, p.ID)
387			}
388			if err := validatePlanRules(p); err != nil {
389				return err
390			}
391		}
392		for id, c := range s.Customers {
393			if c == nil {
394				return fmt.Errorf("客户 %q 的数据为空", id)
395			}
396			if c.ID != id {
397				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
398			}
399			if c.ID == "" || c.Name == "" {
400				return fmt.Errorf("客户 %q 的标识或名称为空", id)
401			}
402			if c.Price < 0 {
403				return fmt.Errorf("客户 %q 单价为负", id)
404			}
405			if c.PlanID != "" {
406				if _, ok := s.Plans[c.PlanID]; !ok {
407					return fmt.Errorf("客户 %q 绑定了不存在的方案 %q", id, c.PlanID)
408				}
409			}
410		}
411		// 方案变更：键、客户（须为绑定阶梯方案的客户）、目标方案、生效月与
412		// 原因都必须自洽；同一客户的变更生效月由键保证唯一。
413		for key, ch := range s.PlanChanges {
414			if ch == nil {
415				return fmt.Errorf("方案变更 %q 的数据为空", key)
416			}
417			if planChangeKey(ch.CustomerID, ch.Month) != key {
418				return fmt.Errorf("方案变更键不一致: 键 %q / 客户月份 %s|%s", key, ch.CustomerID, ch.Month)
419			}
420			c, ok := s.Customers[ch.CustomerID]
421			if !ok {
422				return fmt.Errorf("方案变更 %q 引用了不存在的客户 %q", key, ch.CustomerID)
423			}
424			if c.PlanID == "" {
425				return fmt.Errorf("方案变更 %q 的客户 %q 未绑定阶梯方案", key, ch.CustomerID)
426			}
427			if !validMonth(ch.Month) {
428				return fmt.Errorf("方案变更 %q 的生效月无效", key)
429			}
430			if _, ok := s.Plans[ch.PlanID]; !ok {
431				return fmt.Errorf("方案变更 %q 引用了不存在的方案 %q", key, ch.PlanID)
432			}
433			if strings.TrimSpace(ch.Reason) == "" {
434				return fmt.Errorf("方案变更 %q 的原因为空", key)
435			}
436		}
437		for id, u := range s.Usage {
438			if u == nil {
439				return fmt.Errorf("用量 %q 的数据为空", id)
440			}
441			if u.ID != id {
442				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
443			}
444			if u.ID == "" {
445				return errors.New("存在空的用量标识")
446			}
447			if _, ok := s.Customers[u.CustomerID]; !ok {
448				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
449			}
450			if u.Quantity <= 0 {
451				return fmt.Errorf("用量 %q 的数量非正", u.ID)
452			}
453			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
454				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
455			}
456		}
457		// 撤回标记：键与记录一致、目标用量存在（撤回目标失效即损坏）、原因非空。
458		// 原用量记录仍按上面的规则完整校验（格式、正数量、客户存在性），撤回不
459		// 删除或改写原记录。旧文件缺少撤回记录视为全部用量有效（Withdrawals 已
460		// 在载入时补为空表）。
461		for id, w := range s.Withdrawals {
462			if w == nil {
463				return fmt.Errorf("用量 %q 的撤回记录为空", id)
464			}
465			if w.UsageID != id {
466				return fmt.Errorf("撤回记录键不一致: 键 %q / 用量标识 %q", id, w.UsageID)
467			}
468			if w.UsageID == "" {
469				return errors.New("存在空用量标识的撤回记录")
470			}
471			if _, ok := s.Usage[w.UsageID]; !ok {
472				return fmt.Errorf("撤回记录引用了不存在的用量 %q（撤回目标失效）", w.UsageID)
473			}
474			if strings.TrimSpace(w.Reason) == "" {
475				return fmt.Errorf("用量 %q 的撤回原因为空", w.UsageID)
476			}
477		}
478		// 用量更正关联：键与原标识一致；原记录与替代记录都必须存在于 Usage，
479		// 替代记录内容（客户、解析后的时间点、数量）须与更正保存的新内容一致；
480		// 原记录必须已按更正原因撤回（撤回标记的原因与更正原因不符即损坏）；
481		// 同一替代记录只能有一个来源；关联不得成环。替代记录后来被合法撤回或
482		// 继续更正（即它本身又作为某条更正的原记录）属正常状态，不判为损坏。
483		// 旧文件缺少更正记录视为无更正（UsageCorrections 已在载入时补为空表）。
484		replacementSources := make(map[string]string) // 替代用量标识 -> 原用量标识
485		for id, uc := range s.UsageCorrections {
486			if uc == nil {
487				return fmt.Errorf("用量更正 %q 的数据为空", id)
488			}
489			if uc.UsageID != id {
490				return fmt.Errorf("用量更正键不一致: 键 %q / 原用量标识 %q", id, uc.UsageID)
491			}
492			if uc.UsageID == "" {
493				return errors.New("存在空原用量标识的更正记录")
494			}
495			if strings.TrimSpace(uc.Reason) == "" {
496				return fmt.Errorf("用量更正 %q 的原因为空", id)
497			}
498			orig, ok := s.Usage[uc.UsageID]
499			if !ok {
500				return fmt.Errorf("用量更正 %q 引用了不存在的原用量 %q（更正来源失效）", id, uc.UsageID)
501			}
502			// 原记录内容不可改写：原用量记录仍须是正常的正数量有效格式（已在
503			// 上面的用量校验中核验），此处仅确认其存在。
504			if orig.ID != uc.UsageID {
505				return fmt.Errorf("用量更正 %q 的原记录标识不一致", id)
506			}
507			if uc.ReplacementID == "" {
508				return fmt.Errorf("用量更正 %q 缺少替代用量标识", id)
509			}
510			if uc.ReplacementID == uc.UsageID {
511				return fmt.Errorf("用量更正 %q 的替代标识与原标识相同", id)
512			}
513			repl, ok := s.Usage[uc.ReplacementID]
514			if !ok {
515				return fmt.Errorf("用量更正 %q 引用了不存在的替代用量 %q（更正目标失效）", id, uc.ReplacementID)
516			}
517			if src, dup := replacementSources[uc.ReplacementID]; dup {
518				return fmt.Errorf("替代用量 %q 同时是用量 %q 与 %q 的更正替代（同一替代记录不得有多个来源）",
519					uc.ReplacementID, src, uc.UsageID)
520			}
521			replacementSources[uc.ReplacementID] = uc.UsageID
522			if _, ok := s.Customers[uc.NewCustomerID]; !ok {
523				return fmt.Errorf("用量更正 %q 引用了不存在的新客户 %q", id, uc.NewCustomerID)
524			}
525			nt, err := time.Parse(time.RFC3339, uc.NewTime)
526			if err != nil {
527				return fmt.Errorf("用量更正 %q 的新时间不是 RFC3339: %w", id, err)
528			}
529			if uc.NewQuantity <= 0 {
530				return fmt.Errorf("用量更正 %q 的新数量非正", id)
531			}
532			rt, err := time.Parse(time.RFC3339, repl.Time)
533			if err != nil {
534				return fmt.Errorf("用量更正 %q 的替代记录 %q 时间不是 RFC3339: %w", id, uc.ReplacementID, err)
535			}
536			// 替代记录内容（客户、解析后的时间点、数量）必须与更正保存的新内容一致；
537			// 时间按瞬间比较，Z 与 +08:00 表示同一时刻视为一致。
538			if repl.CustomerID != uc.NewCustomerID || repl.Quantity != uc.NewQuantity || !rt.Equal(nt) {
539				return fmt.Errorf("用量更正 %q 的替代记录 %q 内容与保存的新内容不一致（更正关联损坏）",
540					id, uc.ReplacementID)
541			}
542			// 原记录必须已撤回，且撤回原因就是更正原因。
543			w, ok := s.Withdrawals[uc.UsageID]
544			if !ok {
545				return fmt.Errorf("用量更正 %q 的原用量 %q 未撤回（更正须把原记录按更正原因标记撤回）", id, uc.UsageID)
546			}
547			if w.Reason != uc.Reason {
548				return fmt.Errorf("用量更正 %q 的原用量 %q 撤回原因 %q 与更正原因 %q 不符",
549					id, uc.UsageID, w.Reason, uc.Reason)
550			}
551		}
552		// 关联成环检测：沿“原记录 -> 替代记录”的更正链前进，重复访问即成环。
553		// 合法链必然终止于一条未再被更正的记录。
554		for id := range s.UsageCorrections {
555			seen := map[string]bool{id: true}
556			cur := id
557			for {
558				uc, ok := s.UsageCorrections[cur]
559				if !ok {
560					break // 链终止于未再被更正的记录
561				}
562				if seen[uc.ReplacementID] {
563					return fmt.Errorf("用量更正关联在 %q 处成环（更正链不得成环）", uc.ReplacementID)
564				}
565				seen[uc.ReplacementID] = true
566				cur = uc.ReplacementID
567			}
568		}
569		for key, b := range s.Bills {
570			if b == nil {
571				return fmt.Errorf("账单 %q 的数据为空", key)
572			}
573			if billKey(b.CustomerID, b.Month) != key {
574				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
575			}
576			if _, ok := s.Customers[b.CustomerID]; !ok {
577				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
578			}
579			if !validMonth(b.Month) {
580				return fmt.Errorf("账单 %q 的月份无效", key)
581			}
582			if b.MonthlyFee < 0 {
583				return fmt.Errorf("账单 %q 的月费为负", key)
584			}
585			// 仅月费大于 0 的账单允许空用量明细（无用量也须出账收取月费）。
586			if len(b.Lines) == 0 && b.MonthlyFee == 0 {
587				return fmt.Errorf("账单 %q 没有明细", key)
588			}
589			var qty, fee int64
590			for _, ln := range b.Lines {
591				u, ok := s.Usage[ln.UsageID]
592				if !ok {
593					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
594				}
595				// 已撤回用量不参与结算，账单不得把已撤回记录视为待计费用量。
596				if _, withdrawn := s.Withdrawals[ln.UsageID]; withdrawn {
597					return fmt.Errorf("账单 %q 引用了已撤回的用量 %q", key, ln.UsageID)
598				}
599				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
600					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
601				}
602				if !inMonth(u.Time, b.Month) {
603					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
604				}
605				var err error
606				qty, err = add64(qty, ln.Quantity)
607				if err != nil {
608					return fmt.Errorf("账单 %q 汇总数量溢出", key)
609				}
610				fee, err = add64(fee, ln.LineFee)
611				if err != nil {
612					return fmt.Errorf("账单 %q 汇总金额溢出", key)
613				}
614			}
615			if qty != b.TotalQty {
616				return fmt.Errorf("账单 %q 总数量与明细不符", key)
617			}
618			// 原总金额 = 月费 + 全月用量费；月费不计入逐条用量小计，故明细
619			// 小计之和等于用量费（总金额 − 月费）。月费与总金额均非负，相减
620			// 不会溢出；总金额为负或小于月费时此处必然不符。
621			if usageFee := b.TotalFee - b.MonthlyFee; fee != usageFee {
622				return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费（明细小计合计 %d 分，月费 %d 分，总金额 %d 分）",
623					key, fee, b.MonthlyFee, b.TotalFee)
624			}
625			c := s.Customers[b.CustomerID]
626			switch b.Pricing {
627			case "", "fixed":
628				// 固定单价账单：每条小计必须等于 数量×客户固定单价，且不得
629				// 携带阶梯方案信息、分段或月费。
630				if b.PlanID != "" || b.PlanName != "" || len(b.PlanTiers) > 0 || len(b.TierTotals) > 0 {
631					return fmt.Errorf("账单 %q 是固定单价账单但携带阶梯方案信息", key)
632				}
633				if b.MonthlyFee != 0 {
634					return fmt.Errorf("账单 %q 是固定单价账单但携带月费", key)
635				}
636				for _, ln := range b.Lines {
637					if len(ln.Segments) > 0 {
638						return fmt.Errorf("账单 %q 的明细 %q 携带阶梯分段", key, ln.UsageID)
639					}
640					lf, err := mul64(ln.Quantity, c.Price)
641					if err != nil {
642						return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
643					}
644					if lf != ln.LineFee {
645						return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
646					}
647				}
648				if b.UnitPrice != c.Price {
649					return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
650				}
651			case "tiered":
652				if err := s.validateTieredBill(key, b, c); err != nil {
653					return err
654				}
655			default:
656				return fmt.Errorf("账单 %q 的计价类型 %q 未知", key, b.Pricing)
657			}
658			// 封账期内不得存在游离于账单之外的有效用量（封账后新增被禁止，
659			// 而已入账记录理应全部在明细中）；已撤回用量不计费用，允许存在
660			// 于已封账月份而不进入账单。
661			for _, u := range s.Usage {
662				if _, withdrawn := s.Withdrawals[u.ID]; withdrawn {
663					continue
664				}
665				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
666					found := false
667					for _, ln := range b.Lines {
668						if ln.UsageID == u.ID {
669							found = true
670							break
671						}
672					}
673					if !found {
674						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
675					}
676				}
677			}
678		}
679	
680		// 暂停区间：键、客户（须为绑定阶梯方案的客户）、区间与原因都必须自洽；
681		// 同一客户的当前有效区间不得重叠（可以相接）；有效暂停月内不得存在有效
682		// （未撤回）用量或账单。登记提前恢复后原区间与原因仍永久保留，仅当前
683		// 有效区间缩短为 [原起月, 恢复月)。
684		// 旧文件缺少暂停记录视为正常服务（Suspensions 已在载入时补为空表）。
685		for key, su := range s.Suspensions {
686			if su == nil {
687				return fmt.Errorf("暂停区间 %q 的数据为空", key)
688			}
689			if suspensionKey(su.CustomerID, su.StartMonth) != key {
690				return fmt.Errorf("暂停区间键不一致: 键 %q / 客户起月 %s|%s", key, su.CustomerID, su.StartMonth)
691			}
692			c, ok := s.Customers[su.CustomerID]
693			if !ok {
694				return fmt.Errorf("暂停区间 %q 引用了不存在的客户 %q", key, su.CustomerID)
695			}
696			if c.PlanID == "" {
697				return fmt.Errorf("暂停区间 %q 的客户 %q 未绑定阶梯方案（固定单价客户不适用暂停）", key, su.CustomerID)
698			}
699			if !validMonth(su.StartMonth) {
700				return fmt.Errorf("暂停区间 %q 的起月无效", key)
701			}
702			if !validMonth(su.EndMonth) || su.EndMonth <= su.StartMonth {
703				return fmt.Errorf("暂停区间 %q 的结束月无效（结束月必须是晚于起月 %s 的 YYYY-MM）", key, su.StartMonth)
704			}
705			if strings.TrimSpace(su.Reason) == "" {
706				return fmt.Errorf("暂停区间 %q 的原因为空", key)
707			}
708		}
709		// 暂停提前恢复记录：键与客户/原起月一致；引用的目标暂停必须存在（恢复
710		// 引用缺失即损坏）；恢复月必须是严格介于原起月与原结束月之间的 YYYY-MM；
711		// 原因非空。原区间、原原因与恢复记录都永久保留，不可改写或撤销。旧文件
712		// 缺少恢复记录时暂停沿用原区间（SuspensionResumes 已在载入时补为空表）。
713		for key, r := range s.SuspensionResumes {
714			if r == nil {
715				return fmt.Errorf("暂停提前恢复 %q 的数据为空", key)
716			}
717			if suspensionKey(r.CustomerID, r.StartMonth) != key {
718				return fmt.Errorf("暂停提前恢复键不一致: 键 %q / 客户原起月 %s|%s", key, r.CustomerID, r.StartMonth)
719			}
720			su, ok := s.Suspensions[key]
721			if !ok {
722				return fmt.Errorf("暂停提前恢复 %q 引用了不存在的暂停（客户 %q 原起月 %q，恢复目标缺失）", key, r.CustomerID, r.StartMonth)
723			}
724			if !validMonth(r.ResumeMonth) {
725				return fmt.Errorf("暂停提前恢复 %q 的恢复月无效（必须是 YYYY-MM）", key)
726			}
727			if r.ResumeMonth <= su.StartMonth || r.ResumeMonth >= su.EndMonth {
728				return fmt.Errorf("暂停提前恢复 %q 的恢复月 %s 越界（必须严格满足 原起月 %s < 恢复月 < 原结束月 %s）",
729					key, r.ResumeMonth, su.StartMonth, su.EndMonth)
730			}
731			if strings.TrimSpace(r.Reason) == "" {
732				return fmt.Errorf("暂停提前恢复 %q 的原因为空", key)
733			}
734		}
735		for customerID := range s.Customers {
736			list := s.suspensionsFor(customerID)
737			for i := 1; i < len(list); i++ {
738				// 区间重叠按当前有效区间判断：提前恢复只缩短目标区间，其他暂停
739				// 独立生效；区间仍可相接（相接视为连续暂停）。
740				if list[i].StartMonth < s.suspensionEffectiveEnd(list[i-1]) {
741					return fmt.Errorf("客户 %s 的暂停有效区间 %s..%s 与 %s..%s 重叠（区间可以相接但不得重叠）",
742						customerID,
743						list[i-1].StartMonth, s.suspensionEffectiveEnd(list[i-1]),
744						list[i].StartMonth, s.suspensionEffectiveEnd(list[i]))
745				}
746			}
747			for _, su := range list {
748				// 有效暂停月为 [原起月, 当前有效结束月)：提前恢复释放的月份正常
749				// 服务，允许存在用量与账单。
750				effEnd := s.suspensionEffectiveEnd(su)
751				for _, u := range s.Usage {
752					// 已撤回用量不参与用量冲突判断，可存在于随后暂停的月份。
753					if _, withdrawn := s.Withdrawals[u.ID]; withdrawn {
754						continue
755					}
756					if u.CustomerID == customerID && monthInRange(utcMonth(u.Time), su.StartMonth, effEnd) {
757						return fmt.Errorf("客户 %s 在暂停有效区间 %s..%s（不含结束月）内存在用量 %q（%s）",
758							customerID, su.StartMonth, effEnd, u.ID, utcMonth(u.Time))
759					}
760				}
761				for _, b := range s.Bills {
762					if b.CustomerID == customerID && monthInRange(b.Month, su.StartMonth, effEnd) {
763						return fmt.Errorf("客户 %s 在暂停有效区间 %s..%s（不含结束月）内存在账单（月份 %s），暂停月不得封账",
764							customerID, su.StartMonth, effEnd, b.Month)
765					}
766				}
767			}
768		}
769	
770		// 调整与收款记录：标识、内容、引用与序号都必须自洽。
771		// 调整与收款共用同一个全局操作序号池；两者标识命名空间相互独立，
772		// 允许同名，各自判重与撤销。
773		if s.NextSeq < 0 {
774			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
775		}
776		seenSeq := make(map[int64]string) // 全局操作序号（登记与撤销共用同一池）-> 来源描述
777		for id, a := range s.Adjustments {
778			if a == nil {
779				return fmt.Errorf("调整 %q 的数据为空", id)
780			}
781			if a.ID != id {
782				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
783			}
784			if a.ID == "" {
785				return errors.New("存在空的调整标识")
786			}
787			if a.Amount == 0 {
788				return fmt.Errorf("调整 %q 的金额为零", id)
789			}
790			if strings.TrimSpace(a.Reason) == "" {
791				return fmt.Errorf("调整 %q 的原因为空", id)
792			}
793			if !validMonth(a.Month) {
794				return fmt.Errorf("调整 %q 的月份无效", id)
795			}
796			if _, ok := s.Customers[a.CustomerID]; !ok {
797				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
798			}
799			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
800				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
801			}
802			if a.Seq < 1 || a.Seq > s.NextSeq {
803				return fmt.Errorf("调整 %q 的操作序号越界", id)
804			}
805			if prev, dup := seenSeq[a.Seq]; dup {
806				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
807			}
808			seenSeq[a.Seq] = "调整 " + id
809			if a.Revoked {
810				if strings.TrimSpace(a.RevokeReason) == "" {
811					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
812				}
813				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
814					return fmt.Errorf("调整 %q 的撤销序号越界", id)
815				}
816				if prev, dup := seenSeq[a.RevokeSeq]; dup {
817					return fmt.Errorf("撤销调整 %q 与 %q 的操作序号重复", id, prev)
818				}
819				seenSeq[a.RevokeSeq] = "撤销调整 " + id
820			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
821				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
822			}
823		}
824		for id, p := range s.Payments {
825			if p == nil {
826				return fmt.Errorf("收款 %q 的数据为空", id)
827			}
828			if p.ID != id {
829				return fmt.Errorf("收款标识不一致: 键 %q / 记录 %q", id, p.ID)
830			}
831			if p.ID == "" {
832				return errors.New("存在空的收款标识")
833			}
834			if p.Total <= 0 {
835				return fmt.Errorf("收款 %q 的总额不是正整数", id)
836			}
837			if strings.TrimSpace(p.Note) == "" {
838				return fmt.Errorf("收款 %q 的备注为空", id)
839			}
840			if _, ok := s.Customers[p.CustomerID]; !ok {
841				return fmt.Errorf("收款 %q 引用了不存在的客户 %q", id, p.CustomerID)
842			}
843			if len(p.Allocations) == 0 {
844				return fmt.Errorf("收款 %q 没有分配", id)
845			}
846			seenMonths := make(map[string]bool)
847			var sum int64
848			for _, al := range p.Allocations {
849				if !validMonth(al.Month) {
850					return fmt.Errorf("收款 %q 的分配月份 %q 无效", id, al.Month)
851				}
852				if seenMonths[al.Month] {
853					return fmt.Errorf("收款 %q 的分配月份 %s 重复", id, al.Month)
854				}
855				seenMonths[al.Month] = true
856				if al.Amount <= 0 {
857					return fmt.Errorf("收款 %q 在 %s 的分配金额不是正整数", id, al.Month)
858				}
859				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
860					return fmt.Errorf("收款 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
861				}
862				var err error
863				sum, err = add64(sum, al.Amount)
864				if err != nil {
865					return fmt.Errorf("收款 %q 的分配金额汇总溢出: %w", id, err)
866				}
867			}
868			if sum != p.Total {
869				return fmt.Errorf("收款 %q 的分配合计 %d 分与总额 %d 分不一致", id, sum, p.Total)
870			}
871			if p.Seq < 1 || p.Seq > s.NextSeq {
872				return fmt.Errorf("收款 %q 的操作序号越界", id)
873			}
874			if prev, dup := seenSeq[p.Seq]; dup {
875				return fmt.Errorf("收款 %q 与 %q 的操作序号重复", id, prev)
876			}
877			seenSeq[p.Seq] = "收款 " + id
878			if p.Revoked {
879				if strings.TrimSpace(p.RevokeReason) == "" {
880					return fmt.Errorf("收款 %q 已撤销但撤销原因为空", id)
881				}
882				if p.RevokeSeq <= p.Seq || p.RevokeSeq > s.NextSeq {
883					return fmt.Errorf("收款 %q 的撤销序号越界", id)
884				}
885				if prev, dup := seenSeq[p.RevokeSeq]; dup {
886					return fmt.Errorf("撤销收款 %q 与 %q 的操作序号重复", id, prev)
887				}
888				seenSeq[p.RevokeSeq] = "撤销收款 " + id
889			} else if p.RevokeReason != "" || p.RevokeSeq != 0 {
890				return fmt.Errorf("收款 %q 未撤销但存在撤销信息", id)
891			}
892		}
893		// 分配更正记录：标识、目标收款、原因、新分配与序号都必须自洽。
894		// 更正标识与收款、调整标识命名空间相互独立，允许同名。
895		for id, c := range s.Corrections {
896			if c == nil {
897				return fmt.Errorf("更正 %q 的数据为空", id)
898			}
899			if c.ID != id {
900				return fmt.Errorf("更正标识不一致: 键 %q / 记录 %q", id, c.ID)
901			}
902			if c.ID == "" {
903				return errors.New("存在空的更正标识")
904			}
905			p, ok := s.Payments[c.PaymentID]
906			if !ok {
907				return fmt.Errorf("更正 %q 引用了不存在的收款 %q", id, c.PaymentID)
908			}
909			if strings.TrimSpace(c.Reason) == "" {
910				return fmt.Errorf("更正 %q 的原因为空", id)
911			}
912			if len(c.Allocations) == 0 {
913				return fmt.Errorf("更正 %q 没有新分配", id)
914			}
915			seenMonths := make(map[string]bool)
916			var sum int64
917			for _, al := range c.Allocations {
918				if !validMonth(al.Month) {
919					return fmt.Errorf("更正 %q 的分配月份 %q 无效", id, al.Month)
920				}
921				if seenMonths[al.Month] {
922					return fmt.Errorf("更正 %q 的分配月份 %s 重复", id, al.Month)
923				}
924				seenMonths[al.Month] = true
925				if al.Amount <= 0 {
926					return fmt.Errorf("更正 %q 在 %s 的分配金额不是正整数", id, al.Month)
927				}
928				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
929					return fmt.Errorf("更正 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
930				}
931				var err error
932				sum, err = add64(sum, al.Amount)
933				if err != nil {
934					return fmt.Errorf("更正 %q 的分配金额汇总溢出: %w", id, err)
935				}
936			}
937			if sum != p.Total {
938				return fmt.Errorf("更正 %q 的分配合计 %d 分与关联收款 %q 的总额 %d 分不一致", id, sum, c.PaymentID, p.Total)
939			}
940			if c.Seq <= p.Seq || c.Seq > s.NextSeq {
941				return fmt.Errorf("更正 %q 的操作序号越界", id)
942			}
943			if p.Revoked && c.Seq > p.RevokeSeq {
944				return fmt.Errorf("更正 %q 的操作序号晚于关联收款 %q 的撤销序号", id, c.PaymentID)
945			}
946			if prev, dup := seenSeq[c.Seq]; dup {
947				return fmt.Errorf("更正 %q 与 %q 的操作序号重复", id, prev)
948			}
949			seenSeq[c.Seq] = "更正 " + id
950		}
951		// 退款记录：标识、目标收款、原因、各月退款与序号都必须自洽。退款标识与
952		// 收款、调整、更正标识命名空间相互独立，允许同名。退款只作用于未撤销
953		// 收款的最新分配涉及的月份；首次退款后该收款不得再更正或整笔撤销，
954		// 因此全部退款都以当前最新分配为准核验，累计不得超退。旧文件缺少退款
955		// 记录视为无退款（Refunds 已在载入时补为空表）。
956		for id, r := range s.Refunds {
957			if r == nil {
958				return fmt.Errorf("退款 %q 的数据为空", id)
959			}
960			if r.ID != id {
961				return fmt.Errorf("退款标识不一致: 键 %q / 记录 %q", id, r.ID)
962			}
963			if r.ID == "" {
964				return errors.New("存在空的退款标识")
965			}
966			p, ok := s.Payments[r.PaymentID]
967			if !ok {
968				return fmt.Errorf("退款 %q 引用了不存在的收款 %q（退款目标失效）", id, r.PaymentID)
969			}
970			if strings.TrimSpace(r.Reason) == "" {
971				return fmt.Errorf("退款 %q 的原因为空", id)
972			}
973			if len(r.Allocations) == 0 {
974				return fmt.Errorf("退款 %q 没有月份金额清单", id)
975			}
976			current := currentAllocations(s, p)
977			seenMonths := make(map[string]bool)
978			for _, al := range r.Allocations {
979				if !validMonth(al.Month) {
980					return fmt.Errorf("退款 %q 的月份 %q 无效", id, al.Month)
981				}
982				if seenMonths[al.Month] {
983					return fmt.Errorf("退款 %q 的月份 %s 重复", id, al.Month)
984				}
985				seenMonths[al.Month] = true
986				if al.Amount <= 0 {
987					return fmt.Errorf("退款 %q 在 %s 的金额不是正整数", id, al.Month)
988				}
989				if allocAmountFor(current, al.Month) <= 0 {
990					return fmt.Errorf("退款 %q 的月份 %s 不在收款 %q 的最新分配中（仅允许退最新分配涉及的月份）", id, al.Month, r.PaymentID)
991				}
992			}
993			if r.Seq <= p.Seq || r.Seq > s.NextSeq {
994				return fmt.Errorf("退款 %q 的操作序号越界", id)
995			}
996			if prev, dup := seenSeq[r.Seq]; dup {
997				return fmt.Errorf("退款 %q 与 %q 的操作序号重复", id, prev)
998			}
999			seenSeq[r.Seq] = "退款 " + id
1000		}
1001		// 逐收款核验退款相关约束：已退款的收款不得被整笔撤销；首次退款后不得
1002		// 再出现更正（最新分配已固定）；各月累计退款不得超过该笔在该月的最新
1003		// 分配（累计超退即余额异常）。
1004		for pid, p := range s.Payments {
1005			refs := refundsFor(s, pid)
1006			if len(refs) == 0 {
1007				continue
1008			}
1009			firstRefundSeq := refs[0].Seq // refundsFor 按序号升序
1010			if p.Revoked {
1011				return fmt.Errorf("收款 %q 已发生退款（首次退款序号 %d）却又被整笔撤销（序号 %d），操作先后非法", pid, firstRefundSeq, p.RevokeSeq)
1012			}
1013			for _, c := range s.Corrections {
1014				if c.PaymentID == pid && c.Seq > firstRefundSeq {
1015					return fmt.Errorf("更正 %q 的序号 %d 晚于收款 %q 的首次退款序号 %d（首次退款后最新分配已固定），操作先后非法", c.ID, c.Seq, pid, firstRefundSeq)
1016				}
1017			}
1018			current := currentAllocations(s, p)
1019			totals := make(map[string]int64)
1020			for _, r := range refs {
1021				for _, al := range r.Allocations {
1022					sum, err := add64(totals[al.Month], al.Amount)
1023					if err != nil {
1024						return fmt.Errorf("收款 %q 在 %s 的累计退款溢出有符号 64 位整数范围，余额异常", pid, al.Month)
1025					}
1026					totals[al.Month] = sum
1027				}
1028			}
1029			for month, refunded := range totals {
1030				if alloc := allocAmountFor(current, month); refunded > alloc {
1031					return fmt.Errorf("收款 %q 在 %s 的累计退款 %d 分超过该月分配 %d 分（累计超退），余额异常", pid, month, refunded, alloc)
1032				}
1033			}
1034		}
1035		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
1036		// 0 与有符号 64 位最大值之间；实收（全部未撤销收款按最新分配在该月
1037		// 计入并扣除退款后的合计）必须满足 0 ≤ 实收 ≤ 当前应付。越界说明
1038		// 金额与记录不一致。
1039		for key, b := range s.Bills {
1040			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
1041			if err != nil {
1042				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
1043			}
1044			received, err := paymentReceived(s, b.CustomerID, b.Month)
1045			if err != nil {
1046				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
1047			}
1048			if received > payable {
1049				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
1050			}
1051		}
1052		return nil
1053	}
