1055	// validatePlanRules 校验阶梯方案的标识、名称、月费与阶梯规则本身自洽：
1056	// 月费为非负整数分，至少一档，有限上限为严格递增的正整数，最后一档无
1057	// 上限，单价非负。
1058	func validatePlanRules(p *plan) error {
1059		if p.ID == "" || p.Name == "" {
1060			return fmt.Errorf("方案 %q 的标识或名称为空", p.ID)
1061		}
1062		if p.MonthlyFee < 0 {
1063			return fmt.Errorf("方案 %q 的月费为负", p.ID)
1064		}
1065		if len(p.Tiers) == 0 {
1066			return fmt.Errorf("方案 %q 至少需要一档阶梯", p.ID)
1067		}
1068		prev := int64(0)
1069		for i, t := range p.Tiers {
1070			if t.Price < 0 {
1071				return fmt.Errorf("方案 %q 第 %d 档单价为负", p.ID, i+1)
1072			}
1073			if i == len(p.Tiers)-1 {
1074				if t.Limit != 0 {
1075					return fmt.Errorf("方案 %q 最后一档必须无上限", p.ID)
1076				}
1077			} else {
1078				if t.Limit <= 0 {
1079					return fmt.Errorf("方案 %q 第 %d 档上限必须是正整数", p.ID, i+1)
1080				}
1081				if t.Limit <= prev {
1082					return fmt.Errorf("方案 %q 的有限上限必须严格递增", p.ID)
1083				}
1084				prev = t.Limit
1085			}
1086		}
1087		return nil
1088	}
