1116	// sortedByInstant 判定用量记录是否按（解析后的时间点升序、同一时间按
1117	// 标识字典序）排列，即阶梯计价的计价顺序。
1118	func sortedByInstant(recs []*usageRecord) bool {
1119		for i := 1; i < len(recs); i++ {
1120			ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
1121			tj, _ := time.Parse(time.RFC3339, recs[i].Time)
1122			ui, uj := ti.UTC(), tj.UTC()
1123			if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
1124				return false
1125			}
1126		}
1127		return true
1128	}
