1130	// validateTieredBill 校验阶梯账单：方案引用有效、快照与方案一致、账单方案
1131	// 符合账期月的方案安排，并按保存的方案规则从零累计重放计价，逐条比对分段、
1132	// 小计、各档合计与总金额；任何不符都视为数据损坏。
1133	func (s *state) validateTieredBill(key string, b *bill, c *customer) error {
1134		if b.PlanID == "" {
1135			return fmt.Errorf("账单 %q 缺少方案标识", key)
1136		}
1137		p, ok := s.Plans[b.PlanID]
1138		if !ok {
1139			return fmt.Errorf("账单 %q 引用了不存在的方案 %q", key, b.PlanID)
1140		}
1141		if b.PlanName != p.Name {
1142			return fmt.Errorf("账单 %q 的方案名称快照与方案 %q 不符", key, b.PlanID)
1143		}
1144		if !tiersEqual(b.PlanTiers, p.Tiers) {
1145			return fmt.Errorf("账单 %q 的方案规则快照与方案 %q 不符", key, b.PlanID)
1146		}
1147		if b.MonthlyFee != p.MonthlyFee {
1148			return fmt.Errorf("账单 %q 的月费快照与方案 %q 不符", key, b.PlanID)
1149		}
1150		// 账单方案必须符合账期安排：创建时绑定的初始方案被生效月不晚于
1151		// 账期月的最后一次变更替换（无变更时即初始绑定，兼容旧存档）。
1152		if want := s.effectivePlanID(c, b.Month); want != b.PlanID {
1153			return fmt.Errorf("账单 %q 的方案 %q 与账期 %s 安排的方案 %q 不一致", key, b.PlanID, b.Month, want)
1154		}
1155		if b.UnitPrice != 0 {
1156			return fmt.Errorf("账单 %q 是阶梯账单但保存了统一单价", key)
1157		}
1158		if len(b.TierTotals) != len(p.Tiers) {
1159			return fmt.Errorf("账单 %q 的分档合计档数与方案规则不符", key)
1160		}
1161		// 明细必须按计价顺序排列（前面已逐条核验与用量记录一致）。
1162		recs := make([]*usageRecord, len(b.Lines))
1163		for i, ln := range b.Lines {
1164			recs[i] = s.Usage[ln.UsageID]
1165		}
1166		if !sortedByInstant(recs) {
1167			return fmt.Errorf("账单 %q 的明细未按计价顺序（时间点升序、同一时间按标识字典序）排列", key)
1168		}
1169		priced, err := tieredPrice(p.Tiers, recs)
1170		if err != nil {
1171			return fmt.Errorf("账单 %q 按方案规则计价失败: %w", key, err)
1172		}
1173		for i, ln := range b.Lines {
1174			if !segmentsEqual(ln.Segments, priced.lines[i].segments) {
1175				return fmt.Errorf("账单 %q 的明细 %q 分段与计价规则不符", key, ln.UsageID)
1176			}
1177			if ln.LineFee != priced.lines[i].fee {
1178				return fmt.Errorf("账单 %q 的明细 %q 小计与计价规则不符", key, ln.UsageID)
1179			}
1180		}
1181		for i, tt := range b.TierTotals {
1182			if tt.Quantity != priced.tierQty[i] || tt.Fee != priced.tierFee[i] {
1183				return fmt.Errorf("账单 %q 的第 %d 档合计与计价规则不符", key, i+1)
1184			}
1185		}
1186		// 原总金额 = 月费 + 全月用量费；月费不进入分档合计与逐条小计。
1187		wantTotal, err := add64(priced.totalFee, b.MonthlyFee)
1188		if err != nil || wantTotal != b.TotalFee {
1189			return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费", key)
1190		}
1191		return nil
1192	}
