1194	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
1195	// 只有完整保存成功后调用方才会向用户报告成功。
1196	func (s *state) save() error {
1197		if err := s.validate(); err != nil {
1198			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
1199		}
1200		data, err := json.MarshalIndent(s, "", "  ")
1201		if err != nil {
1202			return fmt.Errorf("序列化数据失败: %w", err)
1203		}
1204		data = append(data, '\n')
1205	
1206		tmp := s.path + ".tmp"
1207		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
1208		if err != nil {
1209			return fmt.Errorf("写入临时数据文件失败: %w", err)
1210		}
1211		if _, err := f.Write(data); err != nil {
1212			f.Close()
1213			os.Remove(tmp)
1214			return fmt.Errorf("写入临时数据文件失败: %w", err)
1215		}
1216		if err := f.Sync(); err != nil {
1217			f.Close()
1218			os.Remove(tmp)
1219			return fmt.Errorf("同步数据文件失败: %w", err)
1220		}
1221		if err := f.Close(); err != nil {
1222			os.Remove(tmp)
1223			return fmt.Errorf("关闭数据文件失败: %w", err)
1224		}
1225		if err := os.Rename(tmp, s.path); err != nil {
1226			os.Remove(tmp)
1227			return fmt.Errorf("替换数据文件失败: %w", err)
1228		}
1229		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
1230			dir.Sync()
1231			dir.Close()
1232		}
1233		return nil
1234	}
