256	func parsePrice(text string) (int64, error) {
257		text = strings.TrimSpace(text)
258		price, err := strconv.ParseInt(text, 10, 64)
259		if err != nil {
260			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
261		}
262		if price < 0 {
263			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
264		}
265		return price, nil
266	}
