275	func cmdUsageImport(dir, file string) error {
276		var reader io.ReadCloser
277		var source string
278		if file == "-" {
279			reader = io.NopCloser(os.Stdin)
280			source = "标准输入"
281		} else {
282			f, err := os.Open(file)
283			if err != nil {
284				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
285			}
286			reader = f
287			source = file
288		}
289		defer reader.Close()
290	
291		rows, parseErrs := parseUsageFile(reader)
292	
293		s, err := loadStore(dir)
294		if err != nil {
295			return err
296		}
297	
298		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
299		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
300		var problems []string
301		problems = append(problems, parseErrs...)
302	
303		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
304		var ordered []*parsedRow
305		newCount, dupCount := 0, 0
306	
307		for _, r := range rows {
308			cust, ok := s.Customers[r.rec.CustomerID]
309			if !ok {
310				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
311				continue
312			}
313	
314			// 去重判定同时对“库中已有”和“本文件内已出现”生效，且先于暂停、
315			// 封账与金额预检：已存在记录（含已撤回记录）按客户、解析后的时间点
316			// 和数量与原内容判重，相同重放计入重复跳过——即使该月后来已封账、
317			// 暂停或后续方案计价会溢出也不受阻；已撤回记录的重放不会恢复记录。
318			var existing *usageRecord
319			if inStore, ok := s.Usage[r.rec.ID]; ok {
320				existing = inStore
321			} else if inBatch, ok := accepted[r.rec.ID]; ok {
322				existing = &inBatch.rec
323			}
324			if existing != nil {
325				if !sameUsage(existing, &r.rec, r.t) {
326					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
327						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
328					continue
329				}
330				dupCount++
331				continue
332			}
333	
334			// 以下为全新用量：暂停、封账及当前方案下金额预检只约束全新用量。
335			// 暂停月的新用量一律拒绝：按记录时间换算的 UTC 月份判断，处于任一
336			// 暂停区间（含起月、不含结束月）即整批失败并指出行号。
337			rowMonth := r.t.UTC().Format("2006-01")
338			if s.isSuspendedMonth(r.rec.CustomerID, rowMonth) {
339				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 处于暂停区间，暂停服务期间不接收用量（新用量 %q 被拒绝）",
340					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
341				continue
342			}
343			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
344			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
345			// 溢出（金额单位：分）。
346			if cust.PlanID == "" {
347				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
348					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
349					continue
350				}
351			} else {
352				rec := r.rec
353				planID := s.effectivePlanID(cust, rowMonth)
354				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
355					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, rowMonth, planID, err))
356					continue
357				}
358			}
359	
360			// 全新标识：不得进入该客户已封账的 UTC 自然月。
361			if s.sealed(r.rec.CustomerID, rowMonth) {
362				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
363					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
364				continue
365			}
366	
367			rr := r
368			accepted[r.rec.ID] = rr
369			ordered = append(ordered, rr)
370			newCount++
371		}
372	
373		if len(problems) > 0 {
374			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
375		}
376	
377		for _, r := range ordered {
378			rec := r.rec
379			s.Usage[rec.ID] = &rec
380		}
381		if err := s.save(); err != nil {
382			return err
383		}
384		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
385		return nil
386	}
