388	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
389	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
390		cr := csv.NewReader(r)
391		cr.FieldsPerRecord = 4
392		cr.TrimLeadingSpace = true
393	
394		header, err := cr.Read()
395		if err == io.EOF {
396			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
397		}
398		if err != nil {
399			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
400		}
401		for i := range header {
402			header[i] = strings.TrimSpace(header[i])
403		}
404		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
405			header[2] != "time" || header[3] != "quantity" {
406			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
407		}
408	
409		var rows []*parsedRow
410		var problems []string
411		line := 1
412		for {
413			rec, err := cr.Read()
414			if err == io.EOF {
415				break
416			}
417			line++
418			if err != nil {
419				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
420				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
421					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
422					break
423				}
424				continue
425			}
426			for i := range rec {
427				rec[i] = strings.TrimSpace(rec[i])
428			}
429	
430			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
431			if id == "" {
432				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
433				continue
434			}
435			if custID == "" {
436				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
437				continue
438			}
439			t, err := time.Parse(time.RFC3339, ts)
440			if err != nil {
441				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
442				continue
443			}
444			qty, err := strconv.ParseInt(qtyText, 10, 64)
445			if err != nil {
446				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
447				continue
448			}
449			if qty <= 0 {
450				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
451				continue
452			}
453	
454			rows = append(rows, &parsedRow{
455				line: line,
456				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
457				t:    t,
458			})
459		}
460		return rows, problems
461	}
462	
463	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
464	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
465	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
466		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
467			return false
468		}
469		et, err := time.Parse(time.RFC3339, existing.Time)
470		if err != nil {
471			return existing.Time == candidate.Time
472		}
473		return et.Equal(candidateT)
474	}
475	
476	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
477	func validMonth(m string) bool {
478		t, err := time.Parse("2006-01", m)
479		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
480			return false
481		}
482		return true
483	}
484	
485	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
486	func inMonth(rfc3339, month string) bool {
487		t, err := time.Parse(time.RFC3339, rfc3339)
488		if err != nil {
489			return false
490		}
491		return t.UTC().Format("2006-01") == month
492	}
493	
494	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
495	// 入参时间均已在载入/导入时校验为 RFC3339。
496	func utcMonth(rfc3339 string) string {
497		t, _ := time.Parse(time.RFC3339, rfc3339)
498		return t.UTC().Format("2006-01")
499	}
