501	func cmdBillSettle(dir, customerID, month string) error {
502		if !validMonth(month) {
503			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
504		}
505		s, err := loadStore(dir)
506		if err != nil {
507			return err
508		}
509		cust, ok := s.Customers[customerID]
510		if !ok {
511			return fmt.Errorf("客户标识 %q 不存在", customerID)
512		}
513	
514		// 暂停月无论方案月费多少都拒绝结算：不封账、不生成零金额账单。
515		if s.isSuspendedMonth(customerID, month) {
516			return fmt.Errorf("客户 %s 的 %s 处于暂停区间，暂停服务期间不产生月费账单，拒绝结算且不封账", customerID, month)
517		}
518	
519		key := billKey(customerID, month)
520		if existing, ok := s.Bills[key]; ok {
521			// 幂等：同一客户同一月份重复结算，直接返回原账单，
522			// 不重新计费、不产生新账单或调整、不落盘。
523			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
524			printBill(existing, cust, s)
525			return nil
526		}
527	
528		// 归集该客户 UTC 自然月内的全部有效（未撤回）用量，区间为左闭右开
529		// [月初, 下月初)。有效方案月费大于 0 的阶梯客户即使无用量也须出账
530		// （收取一次整月月费）；月费为 0 的方案与固定单价客户无用量时仍拒绝
531		// 结算且不封账。
532		inMonthRecs := monthUsage(s, customerID, month)
533		if len(inMonthRecs) == 0 && !monthlyFeeBillable(s, cust, month) {
534			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
535		}
536	
537		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
538		if cust.PlanID != "" {
539			return settleTiered(s, cust, month, inMonthRecs)
540		}
541	
542		b, err := buildFixedBill(cust, month, inMonthRecs)
543		if err != nil {
544			return fmt.Errorf("%v，拒绝结算且不封账", err)
545		}
546		s.Bills[key] = b
547	
548		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
549		if err := s.save(); err != nil {
550			delete(s.Bills, key)
551			return err
552		}
553		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
554		printBill(b, cust, s)
555		return nil
556	}
