596	// buildFixedBill 为固定单价客户构造账单（不落盘）：逐条 数量×单价 并汇总，
597	// 全程整数运算，任何一步溢出都返回错误。recs 须已按计价顺序排列。
598	func buildFixedBill(cust *customer, month string, recs []*usageRecord) (*bill, error) {
599		lines := make([]billLine, 0, len(recs))
600		var totalQty, totalFee int64
601		for _, u := range recs {
602			lineFee, err := mul64(u.Quantity, cust.Price)
603			if err != nil {
604				return nil, fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出", u.ID, u.Quantity, cust.Price)
605			}
606			if totalQty, err = add64(totalQty, u.Quantity); err != nil {
607				return nil, fmt.Errorf("汇总数量溢出有符号 64 位整数范围")
608			}
609			if totalFee, err = add64(totalFee, lineFee); err != nil {
610				return nil, fmt.Errorf("汇总金额溢出有符号 64 位整数范围")
611			}
612			lines = append(lines, billLine{
613				UsageID:  u.ID,
614				Time:     u.Time,
615				Quantity: u.Quantity,
616				LineFee:  lineFee,
617			})
618		}
619		return &bill{
620			ID:         stableBillID(cust.ID, month),
621			CustomerID: cust.ID,
622			Month:      month,
623			TotalQty:   totalQty,
624			UnitPrice:  cust.Price,
625			TotalFee:   totalFee,
626			Lines:      lines,
627			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
628		}, nil
629	}
630	
631	func sortByInstant(us []*usageRecord) {
632		// 入参时间均已在载入/导入时校验为 RFC3339。
633		sort.Slice(us, func(i, j int) bool {
634			ti, _ := time.Parse(time.RFC3339, us[i].Time)
635			tj, _ := time.Parse(time.RFC3339, us[j].Time)
636			ui, uj := ti.UTC(), tj.UTC()
637			if !ui.Equal(uj) {
638				return ui.Before(uj)
639			}
640			return us[i].ID < us[j].ID
641		})
642	}
