651		adjs := adjustmentsFor(s, b.CustomerID, b.Month)
652		// 收款历史保留所有曾涉及本账单的收款：首次登记或任一次更正分配
653		// 涉及该月即纳入，即使后来被更正移出。
654		pays := paymentsEverFor(s, b.CustomerID, b.Month)
655		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
656		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
657		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
658		tiered := b.Pricing == "tiered"
659		if tiered {
660			// 阶梯账单明确计价类型并展示方案与完整规则，不伪造统一单价。
661			fmt.Fprintf(stdout, "计价类型：阶梯计费（按 UTC 自然月累计用量分档计价，每月从零累计）\n")
662			fmt.Fprintf(stdout, "方案：%s（%s）\n", b.PlanID, b.PlanName)
663			fmt.Fprintln(stdout, "阶梯规则：")
664			for i, t := range b.PlanTiers {
665				if t.Limit == 0 {
666					fmt.Fprintf(stdout, "  第 %d 档：累计数量无上限，单价 %d 分（%s）\n", i+1, t.Price, moneyFen(t.Price))
667				} else {
668					fmt.Fprintf(stdout, "  第 %d 档：累计上限 %d，单价 %d 分（%s）\n", i+1, t.Limit, t.Price, moneyFen(t.Price))
669				}
670			}
671		} else {
672			fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
673		}
674		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
675		if tiered {
676			// 阶梯账单分列月费与用量费：原总金额 = 月费 + 全月用量费；
677			// 月费不计入总数量、各档金额或逐条小计。
678			usageFee := b.TotalFee - b.MonthlyFee
679			fmt.Fprintf(stdout, "月费：%d 分（%s，整月收取，不按天折算）\n", b.MonthlyFee, moneyFen(b.MonthlyFee))
680			fmt.Fprintf(stdout, "用量费：%d 分（%s）\n", usageFee, moneyFen(usageFee))
681			fmt.Fprintf(stdout, "原总金额：%d 分（%s，月费加全月用量费）\n", b.TotalFee, moneyFen(b.TotalFee))
682		} else {
683			fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
684		}
685		if tiered {
686			fmt.Fprintln(stdout, "各档合计：")
687			for i, tt := range b.TierTotals {
688				fmt.Fprintf(stdout, "  第 %d 档：数量 %d，单价 %d 分，金额 %d 分（%s）\n",
689					i+1, tt.Quantity, b.PlanTiers[i].Price, tt.Fee, moneyFen(tt.Fee))
690			}
691		}
692		// 数据在载入时已校验一致，此处计算不会出错。
693		net, payable, _ := billTotals(b, adjs)
694		received, _ := paymentReceived(s, b.CustomerID, b.Month)
695		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
696		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
697		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
698		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
699		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
700		if len(b.Lines) == 0 {
701			fmt.Fprintln(stdout, "明细：无（本账期无用量，仅收取月费）")
702		} else {
703			fmt.Fprintln(stdout, "明细：")
704		}
705		for i, ln := range b.Lines {
706			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
707				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
708			// 阶梯账单逐条展示跨档分段的数量、单价与小计。
709			for j, seg := range ln.Segments {
710				fmt.Fprintf(stdout, "     分段 %d：第 %d 档 数量=%d 单价=%d 分 小计=%d 分（%s）\n",
711					j+1, seg.Tier+1, seg.Quantity, b.PlanTiers[seg.Tier].Price, seg.Fee, moneyFen(seg.Fee))
712			}
713		}
714		if len(adjs) == 0 {
715			fmt.Fprintln(stdout, "调整与撤销历史：无")
716		} else {
717			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
718			for i, ev := range historyEvents(adjs) {
719				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
720			}
721		}
722		if len(pays) == 0 {
723			fmt.Fprintln(stdout, "收款与撤销历史：无")
724		} else {
725			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
726			for i, ev := range paymentHistoryEvents(s, pays, b.Month) {
727				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
728			}
729		}
730	}
