732	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
733	func historyEvents(adjs []*adjustment) []string {
734		type event struct {
735			seq  int64
736			text string
737		}
738		var events []event
739		for _, a := range adjs {
740			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
741				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
742			if a.Revoked {
743				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
744					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
745			}
746		}
747		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
748		out := make([]string, len(events))
749		for i, ev := range events {
750			out[i] = ev.text
751		}
752		return out
753	}
754	
755	func adjustKind(amount int64) string {
756		if amount > 0 {
757			return "补收"
758		}
759		return "减免"
760	}
761	
762	func adjustStatus(a *adjustment) string {
763		if a.Revoked {
764			return "已撤销"
765		}
766		return "生效中"
767	}
