769	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
770	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
771	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
772	// 的最新分配。
773	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
774		type event struct {
775			seq  int64
776			text string
777		}
778		var events []event
779		for _, p := range pays {
780			alloc := p.amountFor(month)
781			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
782				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
783			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
784			running := alloc
785			for _, c := range correctionsFor(s, p.ID) {
786				after := allocAmountFor(c.Allocations, month)
787				if running == 0 && after == 0 {
788					continue // 本次更正不涉及本账单
789				}
790				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
791					c.ID, c.Reason, p.ID, running, after)})
792				running = after
793			}
794			if p.Revoked {
795				// 整笔撤销取消的是撤销时的最新分配。
796				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
797					p.ID, p.RevokeReason, p.ID, p.Total, running)})
798			}
799			// 退款在其发生序号减少本账单实收；退款不可撤销，记录永久保留。
800			for _, r := range refundsFor(s, p.ID) {
801				amt := allocAmountFor(r.Allocations, month)
802				if amt <= 0 {
803					continue // 本次退款不涉及本账单
804				}
805				events = append(events, event{r.Seq, fmt.Sprintf("退款 %s：原因：%s（关联收款 %s，本账单退款 %d 分（%s））",
806					r.ID, r.Reason, p.ID, amt, moneyFen(amt))})
807			}
808		}
809		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
810		out := make([]string, len(events))
811		for i, ev := range events {
812			out[i] = ev.text
813		}
814		return out
815	}
816	
817	func paymentStatus(p *payment) string {
818		if p.Revoked {
819			return "已撤销"
820		}
821		return "实收中"
822	}
