824	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
825	func parseAmount(text string) (int64, error) {
826		text = strings.TrimSpace(text)
827		amount, err := strconv.ParseInt(text, 10, 64)
828		if err != nil {
829			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
830		}
831		if amount == 0 {
832			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
833		}
834		return amount, nil
835	}
