837	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
838		if !validMonth(month) {
839			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
840		}
841		if strings.TrimSpace(adjID) == "" {
842			return fmt.Errorf("调整标识不能为空")
843		}
844		amount, err := parseAmount(amountText)
845		if err != nil {
846			return err
847		}
848		if strings.TrimSpace(reason) == "" {
849			return fmt.Errorf("调整原因不能为空")
850		}
851	
852		s, err := loadStore(dir)
853		if err != nil {
854			return err
855		}
856		if _, ok := s.Customers[customerID]; !ok {
857			return fmt.Errorf("客户标识 %q 不存在", customerID)
858		}
859		b, ok := s.Bills[billKey(customerID, month)]
860		if !ok {
861			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
862		}
863	
864		if existing, ok := s.Adjustments[adjID]; ok {
865			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
866			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
867			if existing.CustomerID == customerID && existing.Month == month &&
868				existing.Amount == amount && existing.Reason == reason {
869				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
870				printAdjustment(existing, s)
871				return nil
872			}
873			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
874				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
875		}
876	
877		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
878		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
879		// 不占用该调整标识。
880		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
881		if err != nil {
882			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
883		}
884		received, err := paymentReceived(s, customerID, month)
885		if err != nil {
886			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
887		}
888		newPayable, err := addSigned64(payable, amount)
889		if err != nil {
890			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
891		}
892		if newPayable < 0 {
893			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
894		}
895		if newPayable < received {
896			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
897				newPayable, received, payable, amount)
898		}
899	
900		a := &adjustment{
901			ID:         adjID,
902			CustomerID: customerID,
903			Month:      month,
904			Amount:     amount,
905			Reason:     reason,
906			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
907		}
908		s.NextSeq++
909		a.Seq = s.NextSeq
910		s.Adjustments[adjID] = a
911	
912		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
913		// 该调整标识不被占用。
914		if err := s.save(); err != nil {
915			delete(s.Adjustments, adjID)
916			s.NextSeq--
917			return err
918		}
919		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
920			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
921		printAdjustment(a, s)
922		return nil
923	}
924	
925	func cmdBillRevoke(dir, adjID, reason string) error {
926		if strings.TrimSpace(adjID) == "" {
927			return fmt.Errorf("调整标识不能为空")
928		}
929		if strings.TrimSpace(reason) == "" {
930			return fmt.Errorf("撤销原因不能为空")
931		}
932	
933		s, err := loadStore(dir)
934		if err != nil {
935			return err
936		}
937		a, ok := s.Adjustments[adjID]
938		if !ok {
939			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
940		}
941	
942		if a.Revoked {
943			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
944			// 改用其他原因则拒绝。
945			if a.RevokeReason == reason {
946				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
947				printAdjustment(a, s)
948				return nil
949			}
950			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
951		}
952	
953		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
954		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
955		// 改变余额后重试。
956		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
957		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
958		if err != nil {
959			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
960		}
961		received, err := paymentReceived(s, a.CustomerID, a.Month)
962		if err != nil {
963			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
964		}
965		neg, err := neg64(a.Amount)
966		if err != nil {
967			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
968		}
969		newPayable, err := addSigned64(payable, neg)
970		if err != nil {
971			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
972				payable, a.Amount)
973		}
974		if newPayable < 0 {
975			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
976				newPayable, payable, a.Amount)
977		}
978		if newPayable < received {
979			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
980				newPayable, received, payable, a.Amount)
981		}
982	
983		a.Revoked = true
984		a.RevokeReason = reason
985		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
986		s.NextSeq++
987		a.RevokeSeq = s.NextSeq
988	
989		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
990		if err := s.save(); err != nil {
991			a.Revoked = false
992			a.RevokeReason = ""
993			a.RevokedAt = ""
994			a.RevokeSeq = 0
995			s.NextSeq--
996			return err
997		}
998		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
999			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
1000		printAdjustment(a, s)
1001		return nil
1002	}
