1021	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
1022	func parsePositiveAmount(text string) (int64, error) {
1023		text = strings.TrimSpace(text)
1024		amount, err := strconv.ParseInt(text, 10, 64)
1025		if err != nil {
1026			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
1027		}
1028		if amount <= 0 {
1029			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
1030		}
1031		return amount, nil
1032	}
