1034	func cmdBillPay(dir, customerID, month, payID, amountText, note string) error {
1035		if !validMonth(month) {
1036			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1037		}
1038		amount, err := parsePositiveAmount(amountText)
1039		if err != nil {
1040			return err
1041		}
1042		// 单账单收款视为只有一项分配的汇款，与 bill remit 共用同一核心。
1043		return registerPayment(dir, customerID, payID, amount, note,
1044			[]paymentAllocation{{Month: month, Amount: amount}})
1045	}
