1047	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
1048		total, err := parsePositiveAmount(totalText)
1049		if err != nil {
1050			return err
1051		}
1052		allocs, err := parseAllocations(allocArgs)
1053		if err != nil {
1054			return err
1055		}
1056		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
1057		var sum int64
1058		for _, al := range allocs {
1059			sum, err = add64(sum, al.Amount)
1060			if err != nil {
1061				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
1062			}
1063		}
1064		if sum != total {
1065			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
1066		}
1067		return registerPayment(dir, customerID, payID, total, note, allocs)
1068	}
