1070	// --- 自动分配汇款（bill remit-auto） ---
1071	
1072	// cmdBillRemitAuto 登记一笔自动分配汇款：调用方只提供客户、收款标识、总金额
1073	// 与备注，月份金额由工具确定——首次登记只选择该客户当前已有账单，按 UTC
1074	// 账期月升序依次偿还当前未收余额（调整、最新收款分配、撤销及退款后的净额），
1075	// 跳过余额为 0 的月份，前一月份还清后才分配下一月，最后一月可部分偿还；
1076	// 不补结算、不跨客户、不留未分配款项。无欠款或总金额超过全部欠款时整笔拒绝。
1077	func cmdBillRemitAuto(dir, customerID, payID, totalText, note string) error {
1078		total, err := parsePositiveAmount(totalText)
1079		if err != nil {
1080			return err
1081		}
1082		if strings.TrimSpace(payID) == "" {
1083			return fmt.Errorf("收款标识不能为空")
1084		}
1085		if strings.TrimSpace(note) == "" {
1086			return fmt.Errorf("收款备注不能为空")
1087		}
1088	
1089		s, err := loadStore(dir)
1090		if err != nil {
1091			return err
1092		}
1093		if _, ok := s.Customers[customerID]; !ok {
1094			return fmt.Errorf("客户标识 %q 不存在", customerID)
1095		}
1096	
1097		if existing, ok := s.Payments[payID]; ok {
1098			// 自动登记按客户、总金额、备注判重：相同请求返回原收款及当前状态，
1099			// 不写盘、不重新分配、不增加序号；已撤销或已退款的仍返回当前状态，
1100			// 不恢复旧分配或已退、已撤销金额。
1101			if existing.Auto && existing.CustomerID == customerID &&
1102				existing.Total == total && existing.Note == note {
1103				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同（自动分配登记），返回原收款及当前状态（不写盘、不重新分配、不增加序号）：\n\n", payID)
1104				printAutoPayment(s, existing)
1105				return nil
1106			}
1107			// 同一标识在自动与显式分配登记间复用拒绝；内容不同同样拒绝。
1108			if !existing.Auto {
1109				return fmt.Errorf("收款标识 %q 已由显式分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1110					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1111			}
1112			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q），拒绝复用",
1113				payID, existing.CustomerID, existing.Total, existing.Note)
1114		}
1115	
1116		// 首次登记：归集该客户当前已有账单的月份，按 UTC 账期月升序排列
1117		// （YYYY-MM 字典序即时间序）。不补结算，只有已存在账单参与分配。
1118		var months []string
1119		for _, b := range s.Bills {
1120			if b.CustomerID == customerID {
1121				months = append(months, b.Month)
1122			}
1123		}
1124		sort.Strings(months)
1125	
1126		// 依次偿还当前未收余额：跳过余额为 0 的月份，前一月份还清后才分配
1127		// 下一月，最后一月可部分偿还。每月未收余额 = 当前应付 − 实收，均在
1128		// [0, 有符号 64 位最大值] 内；remaining 从总额（正整数分）起只减不增，
1129		// 各月余额与分配全程整数计算——即使全部账单欠款合计超过 64 位上限，
1130		// 分配过程也只涉及不超过总额的中间值，不会误拒合法金额。
1131		remaining := total
1132		var allocs []paymentAllocation
1133		for _, m := range months {
1134			if remaining == 0 {
1135				break
1136			}
1137			b := s.Bills[billKey(customerID, m)]
1138			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, m))
1139			if err != nil {
1140				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, m, err)
1141			}
1142			received, err := paymentReceived(s, customerID, m)
1143			if err != nil {
1144				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, m, err)
1145			}
1146			outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
1147			if outstanding <= 0 {
1148				continue // 跳过余额为 0 的月份
1149			}
1150			amt := outstanding
1151			if amt > remaining {
1152				amt = remaining // 最后一月可部分偿还
1153			}
1154			allocs = append(allocs, paymentAllocation{Month: m, Amount: amt})
1155			remaining -= amt
1156		}
1157		if len(allocs) == 0 {
1158			return fmt.Errorf("客户 %s 当前没有欠款（全部已存在账单的未收余额均为 0），整笔拒绝；不补结算、不跨客户、不留未分配款项", customerID)
1159		}
1160		if remaining > 0 {
1161			return fmt.Errorf("收款总额 %d 分超过客户 %s 全部已存在账单的欠款合计 %d 分，整笔拒绝；不补结算、不跨客户、不留未分配款项",
1162				total, customerID, total-remaining)
1163		}
1164	
1165		// 成功保存为一笔普通收款及首次自动分配：占用一个账后全局序号，
1166		// 不按月份拆成多笔；可沿用分配更正、整笔撤销、部分退款及退款后
1167		// 固定分配的规则。
1168		p := &payment{
1169			ID:          payID,
1170			CustomerID:  customerID,
1171			Total:       total,
1172			Note:        note,
1173			Allocations: allocs,
1174			Auto:        true,
1175			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1176		}
1177		s.NextSeq++
1178		p.Seq = s.NextSeq
1179		s.Payments[payID] = p
1180	
1181		// 收款记录、首次分配与序号在同一次原子保存中持久化；保存失败则一切
1182		// 不生效，该收款标识与序号不被占用，可原样重试。
1183		if err := s.save(); err != nil {
1184			delete(s.Payments, payID)
1185			s.NextSeq--
1186			return err
1187		}
1188		fmt.Fprintf(stdout, "已按最早欠款账期自动分配并登记收款 %q（总额 %d 分，%s；一次操作，占用一个账后序号）：\n\n",
1189			payID, total, moneyFen(total))
1190		printAutoPayment(s, p)
1191		return nil
1192	}
