1194	// printAutoPayment 输出一笔自动分配登记的收款：收款标识、总额、备注、当前
1195	// 状态、首次分配与最新分配，以及这两份分配所涉月份的当前余额。首次分配
1196	// 永久保留；最新分配经更正变化时以最新为准，退款与撤销不改变首次分配。
1197	func printAutoPayment(s *state, p *payment) {
1198		current := currentAllocations(s, p)
1199		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1200		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1201		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1202		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1203		if p.Revoked {
1204			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1205		} else {
1206			fmt.Fprintf(stdout, "当前状态：实收中\n")
1207		}
1208		fmt.Fprintf(stdout, "首次分配（登记时按最早欠款账期自动确定，永久保留）：%s\n", formatAllocations(p.Allocations))
1209		if sameAllocations(current, p.Allocations) {
1210			fmt.Fprintf(stdout, "最新分配：%s（与首次分配相同）\n", formatAllocations(current))
1211		} else {
1212			fmt.Fprintf(stdout, "最新分配（经更正，以最新为准）：%s\n", formatAllocations(current))
1213		}
1214		fmt.Fprintln(stdout, "首次与最新分配所涉月份当前余额：")
1215		for _, m := range unionMonths(p.Allocations, current) {
1216			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1217			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1218			received, _ := paymentReceived(s, p.CustomerID, m)
1219			fmt.Fprintf(stdout, "  月份 %s：首次分配 %d 分，最新分配 %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1220				m, allocAmountFor(p.Allocations, m), allocAmountFor(current, m),
1221				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1222		}
1223	}
1224	
1225	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
1226	// 月份不得重复，每项金额为正整数分。
1227	func parseAllocations(args []string) ([]paymentAllocation, error) {
1228		if len(args) == 0 {
1229			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
1230		}
1231		seen := make(map[string]bool)
1232		allocs := make([]paymentAllocation, 0, len(args))
1233		for _, arg := range args {
1234			parts := strings.Split(arg, ":")
1235			if len(parts) != 2 {
1236				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
1237			}
1238			month := strings.TrimSpace(parts[0])
1239			if !validMonth(month) {
1240				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
1241			}
1242			if seen[month] {
1243				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
1244			}
1245			seen[month] = true
1246			amount, err := parsePositiveAmount(parts[1])
1247			if err != nil {
1248				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
1249			}
1250			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
1251		}
1252		return allocs, nil
1253	}
1254	
1255	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
1256	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
1257	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
1258		if strings.TrimSpace(payID) == "" {
1259			return fmt.Errorf("收款标识不能为空")
1260		}
1261		if strings.TrimSpace(note) == "" {
1262			return fmt.Errorf("收款备注不能为空")
1263		}
1264		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
1265		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1266	
1267		s, err := loadStore(dir)
1268		if err != nil {
1269			return err
1270		}
1271		if _, ok := s.Customers[customerID]; !ok {
1272			return fmt.Errorf("客户标识 %q 不存在", customerID)
1273		}
1274		for _, al := range allocs {
1275			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1276				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1277			}
1278		}
1279	
1280		if existing, ok := s.Payments[payID]; ok {
1281			// 自动与显式分配登记之间不得复用同一收款标识：标识由 bill remit-auto
1282			// 占用时，bill pay / bill remit 一律拒绝（即使内容碰巧相同）。
1283			if existing.Auto {
1284				return fmt.Errorf("收款标识 %q 已由自动分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1285					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1286			}
1287			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1288			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1289			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1290			if samePaymentContent(existing, customerID, total, note, allocs) {
1291				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1292				printPayment(existing, s)
1293				return nil
1294			}
1295			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1296				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1297		}
1298	
1299		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1300		for _, al := range allocs {
1301			b := s.Bills[billKey(customerID, al.Month)]
1302			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1303			if err != nil {
1304				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1305			}
1306			received, err := paymentReceived(s, customerID, al.Month)
1307			if err != nil {
1308				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1309			}
1310			if payable == 0 {
1311				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1312			}
1313			if al.Amount > payable-received {
1314				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1315					al.Amount, payable-received, customerID, al.Month, payable, received)
1316			}
1317		}
1318	
1319		p := &payment{
1320			ID:          payID,
1321			CustomerID:  customerID,
1322			Total:       total,
1323			Note:        note,
1324			Allocations: allocs,
1325			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1326		}
1327		s.NextSeq++
1328		p.Seq = s.NextSeq
1329		s.Payments[payID] = p
1330	
1331		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1332		// 一切不生效，该收款标识不被占用。
1333		if err := s.save(); err != nil {
1334			delete(s.Payments, payID)
1335			s.NextSeq--
1336			return err
1337		}
1338		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1339		printAllocationBalances(s, p, allocs)
1340		fmt.Fprintln(stdout)
1341		printPayment(p, s)
1342		return nil
1343	}
