1345	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
1346	// 内容相同；分配顺序不影响身份。判重依据首次登记内容，不受后续更正影响。
1347	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
1348		if p.CustomerID != customerID || p.Total != total || p.Note != note {
1349			return false
1350		}
1351		return sameAllocations(p.Allocations, allocs)
1352	}
1353	
1354	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1355	func sameAllocations(a, b []paymentAllocation) bool {
1356		if len(a) != len(b) {
1357			return false
1358		}
1359		for _, al := range b {
1360			if allocAmountFor(a, al.Month) != al.Amount {
1361				return false
1362			}
1363		}
1364		return true
1365	}
