1367	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1368	func formatAllocations(allocs []paymentAllocation) string {
1369		parts := make([]string, len(allocs))
1370		for i, al := range allocs {
1371			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1372		}
1373		return strings.Join(parts, ",")
1374	}
