1387	func cmdBillUnpay(dir, payID, reason string) error {
1388		if strings.TrimSpace(payID) == "" {
1389			return fmt.Errorf("收款标识不能为空")
1390		}
1391		if strings.TrimSpace(reason) == "" {
1392			return fmt.Errorf("撤销原因不能为空")
1393		}
1394	
1395		s, err := loadStore(dir)
1396		if err != nil {
1397			return err
1398		}
1399		p, ok := s.Payments[payID]
1400		if !ok {
1401			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1402		}
1403	
1404		if p.Revoked {
1405			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1406			// 改用其他原因则拒绝。
1407			if p.RevokeReason == reason {
1408				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1409				printPayment(p, s)
1410				return nil
1411			}
1412			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1413		}
1414	
1415		// 首次退款后该收款的最新分配固定，拒绝整笔撤销；退款记录永久保留且
1416		// 不可撤销，实收按扣除退款后的余额继续计算。无退款的收款仍按原规则
1417		// 处理。
1418		if paymentHasRefunds(s, payID) {
1419			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝整笔撤销；如需退回余款请继续登记部分退款", payID)
1420		}
1421	
1422		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1423		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1424		// 分配、更正与撤销原因永久保留。
1425		p.Revoked = true
1426		p.RevokeReason = reason
1427		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1428		s.NextSeq++
1429		p.RevokeSeq = s.NextSeq
1430	
1431		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1432		if err := s.save(); err != nil {
1433			p.Revoked = false
1434			p.RevokeReason = ""
1435			p.RevokedAt = ""
1436			p.RevokeSeq = 0
1437			s.NextSeq--
1438			return err
1439		}
1440		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1441		printAllocationBalances(s, p, currentAllocations(s, p))
1442		fmt.Fprintln(stdout)
1443		printPayment(p, s)
1444		return nil
1445	}
