1447	// printPayment 输出单笔收款记录：总额、首次登记的全部分配（永久保留，
1448	// 判重依据）与当前状态；经历过更正时同时展示当前生效的最新分配。
1449	// 各月应付/实收取自当前库状态。
1450	func printPayment(p *payment, s *state) {
1451		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1452		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1453		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1454		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1455		if p.Revoked {
1456			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1457		} else {
1458			fmt.Fprintf(stdout, "当前状态：实收中\n")
1459		}
1460		fmt.Fprintln(stdout, "分配明细（首次登记，永久保留）：")
1461		for i, al := range p.Allocations {
1462			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1463			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1464			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1465			fmt.Fprintf(stdout, "  %d. 月份 %s：分配 %d 分（%s）；当前应付 %d 分，实收合计 %d 分，未收余额 %d 分\n",
1466				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1467		}
1468		if corrs := correctionsFor(s, p.ID); len(corrs) > 0 {
1469			fmt.Fprintf(stdout, "当前分配（经 %d 次更正，以最新为准）：%s\n",
1470				len(corrs), formatAllocations(currentAllocations(s, p)))
1471		}
1472		if refs := refundsFor(s, p.ID); len(refs) > 0 {
1473			current := currentAllocations(s, p)
1474			fmt.Fprintf(stdout, "退款记录（%d 笔，永久保留、不可撤销；首次退款后最新分配已固定）：\n", len(refs))
1475			for _, r := range refs {
1476				fmt.Fprintf(stdout, "  退款 %s：%s，原因：%s\n", r.ID, formatAllocations(r.Allocations), r.Reason)
1477			}
1478			fmt.Fprintln(stdout, "各月剩余可退额（最新分配减累计退款）：")
1479			for _, al := range current {
1480				refunded := refundedForMonth(s, p.ID, al.Month)
1481				fmt.Fprintf(stdout, "  月份 %s：分配 %d 分，累计已退 %d 分，剩余可退 %d 分（%s）\n",
1482					al.Month, al.Amount, refunded, al.Amount-refunded, moneyFen(al.Amount-refunded))
1483			}
1484		}
1485	}
