1487	// --- 收款分配更正 ---
1488	
1489	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1490		if strings.TrimSpace(payID) == "" {
1491			return fmt.Errorf("收款标识不能为空")
1492		}
1493		if strings.TrimSpace(corrID) == "" {
1494			return fmt.Errorf("更正标识不能为空")
1495		}
1496		if strings.TrimSpace(reason) == "" {
1497			return fmt.Errorf("更正原因不能为空")
1498		}
1499		allocs, err := parseAllocations(allocArgs)
1500		if err != nil {
1501			return err
1502		}
1503		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1504		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1505	
1506		s, err := loadStore(dir)
1507		if err != nil {
1508			return err
1509		}
1510		p, ok := s.Payments[payID]
1511		if !ok {
1512			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1513		}
1514	
1515		if existing, ok := s.Corrections[corrID]; ok {
1516			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1517			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1518			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1519			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1520				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1521				printCorrection(existing, s)
1522				return nil
1523			}
1524			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1525				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1526		}
1527	
1528		// 新增更正只允许未撤销收款。
1529		if p.Revoked {
1530			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1531		}
1532	
1533		// 首次退款后该收款的最新分配固定，拒绝新增分配更正；已有更正的相同
1534		// 重放已在上面按原记录返回，不受此限。无退款的收款仍按原规则处理。
1535		if paymentHasRefunds(s, payID) {
1536			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝新增分配更正", payID)
1537		}
1538	
1539		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1540		var sum int64
1541		for _, al := range allocs {
1542			sum, err = add64(sum, al.Amount)
1543			if err != nil {
1544				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1545			}
1546		}
1547		if sum != p.Total {
1548			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1549		}
1550		// 新分配月份须是原客户的已结算账单。
1551		for _, al := range allocs {
1552			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1553				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1554			}
1555		}
1556	
1557		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1558		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1559		current := currentAllocations(s, p)
1560		for _, m := range unionMonths(current, allocs) {
1561			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1562			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1563			if err != nil {
1564				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1565			}
1566			received, err := paymentReceived(s, p.CustomerID, m)
1567			if err != nil {
1568				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1569			}
1570			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1571			received -= allocAmountFor(current, m)
1572			received, err = add64(received, allocAmountFor(allocs, m))
1573			if err != nil {
1574				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1575			}
1576			if received > payable {
1577				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1578					p.CustomerID, m, received, payable)
1579			}
1580		}
1581	
1582		c := &correction{
1583			ID:          corrID,
1584			PaymentID:   payID,
1585			Reason:      reason,
1586			Allocations: allocs,
1587			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1588		}
1589		s.NextSeq++
1590		c.Seq = s.NextSeq
1591		s.Corrections[corrID] = c
1592	
1593		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1594		// 一切不生效，该更正标识不被占用。
1595		if err := s.save(); err != nil {
1596			delete(s.Corrections, corrID)
1597			s.NextSeq--
1598			return err
1599		}
1600		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1601		printCorrection(c, s)
1602		return nil
1603	}
1604	
1605	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1606	func unionMonths(a, b []paymentAllocation) []string {
1607		set := make(map[string]bool, len(a)+len(b))
1608		for _, al := range a {
1609			set[al.Month] = true
1610		}
1611		for _, al := range b {
1612			set[al.Month] = true
1613		}
1614		months := make([]string, 0, len(set))
1615		for m := range set {
1616			months = append(months, m)
1617		}
1618		sort.Strings(months)
1619		return months
1620	}
1621	
1622	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1623	// 新分配，或（首次更正时）收款的原始分配。
1624	func allocationBefore(s *state, c *correction) []paymentAllocation {
1625		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1626		var latest *correction
1627		for _, o := range s.Corrections {
1628			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1629				latest = o
1630			}
1631		}
1632		if latest != nil {
1633			before = latest.Allocations
1634		}
1635		return before
1636	}
1637	
1638	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1639	// 以及前后分配涉及月份的当前余额。
1640	func printCorrection(c *correction, s *state) {
1641		p := s.Payments[c.PaymentID] // 载入时已校验存在
1642		before := allocationBefore(s, c)
1643		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1644		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1645			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1646		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1647		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1648		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1649		fmt.Fprintln(stdout, "涉及月份当前余额：")
1650		for _, m := range unionMonths(before, c.Allocations) {
1651			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1652			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1653			received, _ := paymentReceived(s, p.CustomerID, m)
1654			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1655				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1656				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1657		}
1658	}
