1660	// --- 账后对账流水 ---
1661	
1662	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1663	// 分配更正、撤销收款或退款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1664	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1665	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值；退款在其发生
1666	// 序号减少本账单实收，不可撤销。
1667	type ledgerEvent struct {
1668		seq           int64  // 全局操作序号（调整/收款/更正/退款及其撤销共用）
1669		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款 / 退款
1670		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1671		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1672		deltaReceived int64  // 对实收的影响（分，带符号）
1673		note          string // 原因（调整/更正类）或备注（收款类）
1674		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1675		payTotal      int64  // 收款类事件：汇款总额
1676		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配；退款事件为本账单退款额）
1677		payID         string // 更正/退款事件：关联收款标识
1678		beforeAlloc   int64  // 更正事件：本账单更正前分配
1679		afterAlloc    int64  // 更正事件：本账单更正后分配
1680		afterPayable  int64  // 事件后的应付（回放时填充）
1681		afterReceived int64  // 事件后的实收（回放时填充）
1682	}
1683	
1684	// billLedger 返回目标账单的一条按操作序号升序的账后流水，事件之后的三项
1685	// 余额已逐步填充。业务归属、金额影响（调整/撤销/收款/更正/撤销收款/退款）
1686	// 与完整性核验都来自与 bill reconcile 共用的 postbill 计算，本处只取该账单
1687	// 那一条流水：
1688	//
1689	//   - 以原总金额为初始应付、零实收为起点；
1690	//   - 回放覆盖完整流水（不受查询截止序号限制），序号重复、撤销先于原操作，
1691	//     或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号 64 位最大值，都视为
1692	//     数据异常并拒绝，即使异常发生在截止序号之后——只检查最终余额会放过
1693	//     中间越界的存档；
1694	//   - 曾涉及该账单的收款在被更正移出该月后，仍保留零金额撤销事件。
1695	//
1696	// 只读：不修改库、不占用序号、不新增记录。
1697	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1698		ops, err := postbillOps(s, b.CustomerID)
1699		if err != nil {
1700			return nil, err
1701		}
1702		ledgers, err := verifyPostbillLedgers(ops, []*bill{b})
1703		if err != nil {
1704			return nil, err
1705		}
1706		return ledgers[b.Month], nil
1707	}
1708	
1709	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1710		if !validMonth(month) {
1711			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1712		}
1713		s, err := loadStore(dir)
1714		if err != nil {
1715			return err
1716		}
1717		cust, ok := s.Customers[customerID]
1718		if !ok {
1719			return fmt.Errorf("客户标识 %q 不存在", customerID)
1720		}
1721		b, ok := s.Bills[billKey(customerID, month)]
1722		if !ok {
1723			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1724		}
1725	
1726		// 截止序号使用调整/收款/更正/退款及其撤销共用的已保存全局序号：省略表示最新，
1727		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1728		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1729		cutoff := s.NextSeq
1730		cutoffDesc := "省略，按最新"
1731		if hasCutoff {
1732			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1733			if perr != nil {
1734				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1735			}
1736			if v < 0 {
1737				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1738			}
1739			if v > s.NextSeq {
1740				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1741			}
1742			cutoff = v
1743			cutoffDesc = "指定"
1744		}
1745	
1746		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1747		// 拒绝，不输出部分正常的报告。
1748		events, err := billLedger(s, b)
1749		if err != nil {
1750			return err
1751		}
1752		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1753		return nil
1754	}
1755	
1756	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1757		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1758		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1759		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1760		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1761		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1762		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1763		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1764			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1765	
1766		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1767		payable, received := b.TotalFee, int64(0)
1768		var shown []ledgerEvent
1769		for _, ev := range events {
1770			if ev.seq > cutoff {
1771				continue
1772			}
1773			shown = append(shown, ev)
1774			payable, received = ev.afterPayable, ev.afterReceived
1775		}
1776		if len(shown) == 0 {
1777			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1778		} else {
1779			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1780			for i, ev := range shown {
1781				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1782			}
1783		}
1784		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1785			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1786	}
1787	
1788	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1789	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1790	// 说明汇款总额与本账单分配。
1791	func formatLedgerEvent(ev ledgerEvent) string {
1792		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1793			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1794		switch ev.kind {
1795		case "调整":
1796			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1797				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1798		case "撤销调整":
1799			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1800				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1801		case "收款":
1802			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1803				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1804		case "更正":
1805			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1806				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1807		case "退款":
1808			return fmt.Sprintf("序号 %d 退款 %s：实收 %+d 分（%s，关联收款 %s，本账单退款 %d 分），原因：%s → %s",
1809				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.payAlloc, ev.note, after)
1810		default: // 撤销收款
1811			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1812				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1813		}
1814	}
1815

