1	package main
2	
3	import (
4		"fmt"
5		"strings"
6	)
7	
8	// 本文件实现按客户账期清单的整批结算（bill settle-batch）：一次确认多项
9	// 客户与 UTC 自然月配对，同时生成账单并封账。整份清单先确认可结算性，
10	// 任一项非法、无用量或计价溢出都拒绝整批；所有新增账单与封账状态在同
11	// 一次原子保存中持久化，完整保存成功后才报告成功。批量结算不新增账后
12	// 事件，也不占用全局操作序号。
13	
14	// buildBill 为未结算的客户月份构造账单（不落盘）：归集该 UTC 自然月的全部
15	// 用量，固定单价客户逐条 数量×单价，阶梯客户按账期月有效方案从零累计分档
16	// 计价（保留跨档明细与方案快照），原总金额含该方案的一次整月月费。没有用量
17	// 且有效方案月费为 0（或固定单价客户），或计价溢出时返回错误。
18	func buildBill(s *state, cust *customer, month string) (*bill, error) {
19		recs := monthUsage(s, cust.ID, month)
20		if len(recs) == 0 && !monthlyFeeBillable(s, cust, month) {
21			return nil, fmt.Errorf("该 UTC 自然月没有用量")
22		}
23		if cust.PlanID != "" {
24			return buildTieredBill(s, cust, month, recs)
25		}
26		return buildFixedBill(cust, month, recs)
27	}
28	
29	// settleItem 是批量结算清单中一项的结算结果。
30	type settleItem struct {
31		pos        int    // 清单中的位置（1 起）
32		customerID string // 客户标识
33		month      string // YYYY-MM（UTC）
34		b          *bill  // 新增或已有的账单
35		isNew      bool   // true 表示本次新增并封账；false 表示返回原账单
36	}
37	
38	func cmdBillSettleBatch(dir string, args []string) error {
39		if len(args) == 0 || len(args)%2 != 0 {
40			return usageError("用法：bill settle-batch <客户标识> <YYYY-MM> [<客户标识> <YYYY-MM> ...]（至少一项配对，参数个数须为偶数）")
41		}
42	
43		s, err := loadStore(dir)
44		if err != nil {
45			return err
46		}
47	
48		// 先校验整份清单：任何问题都在此阶段收集，全部通过后才一次性修改并
49		// 保存，保证任一项非法都整批拒绝，不留下新账单，也不封闭任何月份。
50		var items []settleItem
51		var problems []string
52		seen := make(map[string]int)       // 客户|月份 -> 首次出现的清单位置
53		newBills := make(map[string]*bill) // 本次新增账单（保存失败时整体回滚）
54	
55		for i := 0; i < len(args); i += 2 {
56			pos := i/2 + 1
57			customerID, month := args[i], args[i+1]
58			where := fmt.Sprintf("第 %d 项（客户 %q，月份 %q）", pos, customerID, month)
59			if strings.TrimSpace(customerID) == "" {
60				problems = append(problems, where+"：客户标识不能为空")
61				continue
62			}
63			if !validMonth(month) {
64				problems = append(problems, where+"：月份无效，必须是 YYYY-MM 形式（如 2026-09）")
65				continue
66			}
67			cust, ok := s.Customers[customerID]
68			if !ok {
69				problems = append(problems, where+"：客户不存在")
70				continue
71			}
72			key := billKey(customerID, month)
73			if first, dup := seen[key]; dup {
74				problems = append(problems, fmt.Sprintf("%s：与第 %d 项重复（同一客户同一月份不得在清单中重复出现）", where, first))
75				continue
76			}
77			seen[key] = pos
78	
79			// 暂停月无论方案月费多少都不能结算：清单中任一项落入暂停区间，
80			// 整份清单即拒绝，不生成任何新账单或封账，也不输出部分成功报告。
81			if s.isSuspendedMonth(customerID, month) {
82				problems = append(problems, fmt.Sprintf("%s：该月处于客户的暂停区间（%s），暂停服务期间不产生月费账单",
83					where, describeSuspension(s, customerID, month)))
84				continue
85			}
86			if existing, ok := s.Bills[key]; ok {
87				// 已结算项返回原账单，不重新计费；已有账单的标识、快照、金额与
88				// 账后历史均不改变。
89				items = append(items, settleItem{pos: pos, customerID: customerID, month: month, b: existing})
90				continue
91			}
92			// 未结算项按该账期的计费规则独立计价：不跨客户或月份共享累计量。
93			b, err := buildBill(s, cust, month)
94			if err != nil {
95				problems = append(problems, fmt.Sprintf("%s：%v", where, err))
96				continue
97			}
98			newBills[key] = b
99			items = append(items, settleItem{pos: pos, customerID: customerID, month: month, b: b, isNew: true})
100		}
101	
102		if len(problems) > 0 {
103			return fmt.Errorf("批量结算失败，整批未生效（不新增账单、不封闭任何月份，共 %d 个问题）：\n  %s",
104				len(problems), strings.Join(problems, "\n  "))
105		}
106	
107		// 全部项目已结算时不改写存档；否则所有新账单与封账状态整体原子保存，
108		// 保存失败则整批不生效，原有账单、用量和其他状态不变，可排除故障后
109		// 按原清单重试。
110		newCount := len(newBills)
111		if newCount > 0 {
112			for key, b := range newBills {
113				s.Bills[key] = b
114			}
115			if err := s.save(); err != nil {
116				for key := range newBills {
117					delete(s.Bills, key)
118				}
119				return fmt.Errorf("批量结算保存失败，整批未生效: %w", err)
120			}
121		}
122	
123		// 完整保存成功后才报告成功，按清单顺序逐项列出结果。
124		existingCount := len(items) - newCount
125		if newCount == 0 {
126			fmt.Fprintf(stdout, "批量结算完成：共 %d 项，新增账单 0 张，已有账单 %d 张（全部已结算，未改写存档）：\n",
127				len(items), existingCount)
128		} else {
129			fmt.Fprintf(stdout, "批量结算完成：共 %d 项，新增账单 %d 张（对应月份已封账），已有账单 %d 张：\n",
130				len(items), newCount, existingCount)
131		}
132		for _, it := range items {
133			status := "已有（返回原账单，不重新计费）"
134			if it.isNew {
135				status = "新增（已封账）"
136			}
137			fmt.Fprintf(stdout, "  %d. 客户 %s 月份 %s 账单 %s 原总金额 %d 分（%s）[%s]\n",
138				it.pos, it.customerID, it.month, it.b.ID, it.b.TotalFee, moneyFen(it.b.TotalFee), status)
139		}
140		fmt.Fprintln(stdout, "完整明细可用 bill show <客户标识> <YYYY-MM> 或重复 bill settle 查询。")
141		return nil
142	}
