1	package main
2	
3	import (
4		"fmt"
5		"sort"
6	)
7	
8	// 账后对账共享计算（仅供 bill ledger 与 bill reconcile 两类只读查询使用）。
9	//
10	// 现有结算、账单展示、载入校验与账后登记（adjust/revoke/pay/remit/correct/
11	// unpay/refund）的校验和持久化行为不在本文件内；本文件只把已保存的调整、
12	// 调整撤销、收款、分配更正、收款撤销与退款，按统一的业务归属与金额影响规则
13	// 推导成一组带全局序号的账后操作，再由两类查询各自展开、筛选与展示：
14	//
15	//   - postbillOps 一次构建一个客户全部账后操作（每笔调整/收款/更正/撤销/
16	//     退款各一条），操作自带各账期的应付/实收影响，是两类查询唯一的推导入口；
17	//   - postbillLedger 把操作展开到单张账单的流水（ledger 视图）；
18	//   - postbillRangeEvents 把操作按账期范围与序号区间筛选为报表条目
19	//     （reconcile 视图）；
20	//   - verifyPostbillLedgers 对选中账单做完整流水逐步核验，任何中间异常
21	//     （即使在查询截止之后）都整体拒绝。
22	//
23	// 业务归属与金额影响规则（两类查询共用同一套）：
24	//
25	//   - 流水按全局序号升序，以原总金额为初始应付、零实收起算；指定截止包含
26	//     该序号，对账区间为起点之后、终点以内，合法空档与序号 0 保持；
27	//   - 调整只影响所属账期应付；撤销调整在其发生序号抵消原调整金额；
28	//   - 收款按登记时分配增加对应账期实收；更正按发生时的前后分配替换，撤销
29	//     取消撤销当时的最新分配；退款只减少对应月实收，截止后的操作不能提前
30	//     影响历史余额；
31	//   - 同名调整、收款、更正、退款按类型关联（分别来自各自记录表）。
32	
33	// pbKind 标识账后操作的业务类型。同名标识在不同类型间互不混淆。
34	const (
35		pbAdjust        = "调整"
36		pbAdjustRevoke  = "撤销调整"
37		pbPayment       = "收款"
38		pbCorrection    = "更正"
39		pbPaymentRevoke = "撤销收款"
40		pbRefund        = "退款"
41	)
42	
43	// postbillEffect 是一次账后操作对某一个账期（月份）的金额影响。
44	type postbillEffect struct {
45		month         string
46		deltaPayable  int64 // 对该月应付的影响（分，带符号）
47		deltaReceived int64 // 对该月实收的影响（分，带符号）
48		alloc         int64 // 收款：登记分配；撤销收款：被取消的最新分配；退款：该月退款额
49		beforeAlloc   int64 // 更正：更正前该收款在该月的分配
50		afterAlloc    int64 // 更正：更正后该收款在该月的分配
51	}
52	
53	// postbillOp 是一笔已保存账后业务在共享计算中的统一表示：调整、撤销调整、
54	// 收款、分配更正、撤销收款或退款。effects 给出该操作涉及各账期的金额影响：
55	//
56	//   - 调整/撤销调整：只含所属账期一项应付影响；
57	//   - 收款：按登记时分配，每个分配月份一项实收影响；
58	//   - 更正：以前后分配并集的每个月份一项实收影响（含前后均为 0 时不会
59	//     出现的月份被跳过；前后都涉及但金额相同的月份保留零差额明细）；
60	//   - 撤销收款：撤销当时最新分配的每个月份一项实收影响；
61	//   - 退款：每个退款月份一项实收影响。
62	type postbillOp struct {
63		seq      int64
64		kind     string
65		refID    string // 记录标识（调整、收款、更正或退款标识）
66		note     string // 原因（调整/更正/退款/撤销类）或备注（收款）
67		linkSeq  int64  // 撤销事件关联的原操作序号；非撤销为 0
68		payID    string // 收款自身标识；更正/退款/撤销收款：关联收款标识
69		payTotal int64  // 收款类操作：汇款总额（仅展示用，不计入范围内实收）
70		effects  []postbillEffect
71	}
72	
73	// postbillOps 构建一个客户的全部账后操作，按全局操作序号升序返回。同一全局
74	// 序号的唯一性、撤销先后等完整性问题在 verifyPostbillLedgers 中统一核验；
75	// 这里只做业务归属与金额影响的推导。调整金额为 math.MinInt64 无法抵消时
76	// 直接按数据异常报错。
77	func postbillOps(s *state, customerID string) ([]postbillOp, error) {
78		var ops []postbillOp
79	
80		for _, a := range s.Adjustments {
81			if a.CustomerID != customerID {
82				continue
83			}
84			ops = append(ops, postbillOp{
85				seq: a.Seq, kind: pbAdjust, refID: a.ID, note: a.Reason,
86				effects: []postbillEffect{{
87					month: a.Month, deltaPayable: a.Amount,
88				}},
89			})
90			if a.Revoked {
91				neg, err := neg64(a.Amount)
92				if err != nil {
93					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出对账目", a.ID, a.Amount)
94				}
95				ops = append(ops, postbillOp{
96					seq: a.RevokeSeq, kind: pbAdjustRevoke, refID: a.ID, note: a.RevokeReason,
97					linkSeq: a.Seq,
98					effects: []postbillEffect{{
99						month: a.Month, deltaPayable: neg,
100					}},
101				})
102			}
103		}
104	
105		for _, p := range s.Payments {
106			if p.CustomerID != customerID {
107				continue
108			}
109			// 收款按登记时分配计入实收；多月汇款在每个分配月份各有一项影响，
110			// 调用方按账期筛选时只取本账期/范围内月份，不重复累加汇款总额。
111			op := postbillOp{
112				seq: p.Seq, kind: pbPayment, refID: p.ID, note: p.Note,
113				payID: p.ID, payTotal: p.Total,
114			}
115			for _, al := range p.Allocations {
116				op.effects = append(op.effects, postbillEffect{
117					month: al.Month, deltaReceived: al.Amount, alloc: al.Amount,
118				})
119			}
120			ops = append(ops, op)
121	
122			// 以登记分配为起点按序号回放更正：每次更正按发生时的前后分配计算
123			// 影响。running 始终是该更正发生前生效的分配。
124			running := p.Allocations
125			for _, c := range correctionsFor(s, p.ID) {
126				cop := postbillOp{
127					seq: c.Seq, kind: pbCorrection, refID: c.ID, note: c.Reason,
128					payID: p.ID, payTotal: p.Total,
129				}
130				for _, m := range unionMonths(running, c.Allocations) {
131					b4, af := allocAmountFor(running, m), allocAmountFor(c.Allocations, m)
132					if b4 == 0 && af == 0 {
133						continue
134					}
135					cop.effects = append(cop.effects, postbillEffect{
136						month: m, deltaReceived: af - b4, beforeAlloc: b4, afterAlloc: af,
137					})
138				}
139				ops = append(ops, cop)
140				running = c.Allocations
141			}
142	
143			// 撤销取消的是撤销发生时的最新分配（running 即回放全部更正后的
144			// 分配；更正序号均先于撤销序号）。
145			if p.Revoked {
146				rop := postbillOp{
147					seq: p.RevokeSeq, kind: pbPaymentRevoke, refID: p.ID, note: p.RevokeReason,
148					linkSeq: p.Seq, payID: p.ID, payTotal: p.Total,
149				}
150				for _, al := range running {
151					rop.effects = append(rop.effects, postbillEffect{
152						month: al.Month, deltaReceived: -al.Amount, alloc: al.Amount,
153					})
154				}
155				ops = append(ops, rop)
156			}
157	
158			// 退款只减少对应月实收、不可撤销；退款月份必属于最新分配。
159			// 跨月退款是一次操作，多个月份的影响合并在同一条目下。
160			for _, r := range refundsFor(s, p.ID) {
161				rop := postbillOp{
162					seq: r.Seq, kind: pbRefund, refID: r.ID, note: r.Reason,
163					payID: p.ID, payTotal: p.Total,
164				}
165				for _, al := range r.Allocations {
166					rop.effects = append(rop.effects, postbillEffect{
167						month: al.Month, deltaReceived: -al.Amount, alloc: al.Amount,
168					})
169				}
170				ops = append(ops, rop)
171			}
172		}
173	
174		sort.Slice(ops, func(i, j int) bool { return ops[i].seq < ops[j].seq })
175		return ops, nil
176	}
177	
178	// effectFor 返回一次操作在指定账期上的金额影响；不涉及时第二个返回值为
179	// false。“涉及”以效果项为准：更正前后都不涉及的月份没有效果项，而前后
180	// 分配相同（零差额）的月份仍有效果项。
181	func effectFor(op postbillOp, month string) (postbillEffect, bool) {
182		for _, e := range op.effects {
183			if e.month == month {
184				return e, true
185			}
186		}
187		return postbillEffect{}, false
188	}
189	
190	// postbillLedger 把客户级账后操作展开为单张账单的一条按序号升序流水。
191	// 本函数只负责业务归属与事件展开，不计算事件后余额、不做完整性核验；
192	// 逐步回放、越界检查与事件后余额填充统一由 verifyPostbillLedgers 完成，
193	// 调用方应使用其返回的已核验流水。
194	//
195	// 与报表视图的归属差异仅在筛选层：单账单流水保留曾涉及该账单的收款在被
196	// 更正移出该月之后的零金额撤销事件（撤销当时最新分配已不含本月），以便
197	// 完整呈现该账单历史上出现过的收款；这类撤销在本月金额影响为 0。
198	//
199	// ops 须为 postbillOps 的结果（按序号升序）。
200	func postbillLedger(ops []postbillOp, b *bill) []ledgerEvent {
201		var events []ledgerEvent
202		for _, op := range ops {
203			switch op.kind {
204			case pbAdjust, pbAdjustRevoke:
205				e, ok := effectFor(op, b.Month)
206				if !ok {
207					continue
208				}
209				events = append(events, ledgerEvent{
210					seq: op.seq, kind: op.kind, refID: op.refID,
211					deltaPayable: e.deltaPayable, note: op.note, linkSeq: op.linkSeq,
212				})
213			case pbPayment:
214				e, ok := effectFor(op, b.Month)
215				if !ok {
216					continue // 登记时不涉及本账单的收款，不会因后续更正“补登”收款事件
217				}
218				events = append(events, ledgerEvent{
219					seq: op.seq, kind: op.kind, refID: op.refID,
220					deltaReceived: e.deltaReceived, note: op.note,
221					payTotal: op.payTotal, payAlloc: e.alloc,
222				})
223			case pbCorrection:
224				e, ok := effectFor(op, b.Month)
225				if !ok {
226					continue // 前后分配都不涉及本账单的更正不列示
227				}
228				events = append(events, ledgerEvent{
229					seq: op.seq, kind: op.kind, refID: op.refID,
230					deltaReceived: e.deltaReceived, note: op.note, payID: op.payID,
231					beforeAlloc: e.beforeAlloc, afterAlloc: e.afterAlloc,
232				})
233			case pbPaymentRevoke:
234				// 曾涉及该账单的收款（登记分配或任一次更正的新分配曾落在本
235				// 月）即使在撤销时已被更正移出，也保留零金额撤销事件。
236				if !paymentEverTouched(ops, op.payID, b.Month) {
237					continue
238				}
239				e, ok := effectFor(op, b.Month)
240				var amt int64
241				if ok {
242					amt = e.alloc // 撤销当时最新分配中本账单的金额；移出后为 0
243				}
244				events = append(events, ledgerEvent{
245					seq: op.seq, kind: op.kind, refID: op.refID,
246					deltaReceived: -amt, note: op.note, linkSeq: op.linkSeq,
247					payTotal: op.payTotal, payAlloc: amt,
248				})
249			case pbRefund:
250				e, ok := effectFor(op, b.Month)
251				if !ok {
252					continue
253				}
254				events = append(events, ledgerEvent{
255					seq: op.seq, kind: op.kind, refID: op.refID,
256					deltaReceived: e.deltaReceived, note: op.note, payID: op.payID,
257					payAlloc: e.alloc,
258				})
259			}
260		}
261		return events
262	}
263	
264	// paymentEverTouched 报告某收款是否曾在登记或任一次更正中把分配落到指定
265	// 账期（即使后来被更正移出）。零金额撤销事件的保留只依据“曾经涉及”。
266	func paymentEverTouched(ops []postbillOp, payID, month string) bool {
267		for _, op := range ops {
268			if op.payID != payID {
269				continue
270			}
271			switch op.kind {
272			case pbPayment, pbCorrection:
273				if _, ok := effectFor(op, month); ok {
274					return true
275				}
276			}
277		}
278		return false
279	}
280	
281	// verifyPostbillLedgers 对选中账单逐张做完整流水核验（不受任何查询截止
282	// 序号限制）：逐事件检查该账单流水内序号不重复、撤销严格晚于原操作，且
283	// 每个事件之后都满足 0 ≤ 实收 ≤ 应付 ≤ 有符号 64 位最大值。任一账单的
284	// 任何中间步骤异常都会返回错误，调用方应整体拒绝、不输出部分报告——只
285	// 检查最终余额会放过中间越界的存档。返回按账单月份键控的已核验流水（含
286	// 事件后余额），供两类查询直接复用。
287	//
288	// 逐步累加只把每个事件的金额影响加到运行余额上，不对发生额做累计求和，
289	// 因此累计补收/收款发生额超过 64 位上限但每步余额合法时仍能成功。
290	func verifyPostbillLedgers(ops []postbillOp, bills []*bill) (map[string][]ledgerEvent, error) {
291		ledgers := make(map[string][]ledgerEvent, len(bills))
292		for _, b := range bills {
293			events := postbillLedger(ops, b)
294			payable, received := b.TotalFee, int64(0)
295			seen := make(map[int64]string, len(events))
296			for i := range events {
297				ev := &events[i]
298				desc := ev.kind + " " + ev.refID
299				if prev, dup := seen[ev.seq]; dup {
300					return nil, fmt.Errorf("流水序号 %d 重复（%s 与 %s），数据异常，拒绝输出对账目", ev.seq, prev, desc)
301				}
302				seen[ev.seq] = desc
303				if ev.linkSeq != 0 && ev.linkSeq >= ev.seq {
304					return nil, fmt.Errorf("%s 的撤销序号 %d 不晚于原操作序号 %d，数据异常，拒绝输出对账目", desc, ev.seq, ev.linkSeq)
305				}
306				var err error
307				if payable, err = addSigned64(payable, ev.deltaPayable); err != nil {
308					return nil, fmt.Errorf("序号 %d（%s）之后应付越出有符号 64 位整数范围，数据异常，拒绝输出对账目", ev.seq, desc)
309				}
310				if received, err = addSigned64(received, ev.deltaReceived); err != nil {
311					return nil, fmt.Errorf("序号 %d（%s）之后实收越出有符号 64 位整数范围，数据异常，拒绝输出对账目", ev.seq, desc)
312				}
313				if payable < 0 {
314					return nil, fmt.Errorf("序号 %d（%s）之后应付为 %d 分（小于 0），数据异常，拒绝输出对账目", ev.seq, desc, payable)
315				}
316				if received < 0 {
317					return nil, fmt.Errorf("序号 %d（%s）之后实收为 %d 分（小于 0），数据异常，拒绝输出对账目", ev.seq, desc, received)
318				}
319				if received > payable {
320					return nil, fmt.Errorf("序号 %d（%s）之后实收 %d 分超过应付 %d 分，数据异常，拒绝输出对账目", ev.seq, desc, received, payable)
321				}
322				ev.afterPayable = payable
323				ev.afterReceived = received
324			}
325			ledgers[b.Month] = events
326		}
327		return ledgers, nil
328	}
329	
330	// postbillRangeEvents 把客户级账后操作筛选为跨账期报表区间内的操作条目：
331	// 账期范围 [startMonth, endMonth]（包含首尾），序号区间 (startSeq, endSeq]
332	// （起点之后、终点以内）。每次操作只出现一次，只保留落在范围内账期的
333	// 效果项；操作在范围内没有任何账期效果时不列示。
334	//
335	// 撤销收款只按撤销当时最新分配判断是否涉及范围（effects 即最新分配），
336	// 不因曾经涉及范围而增加操作——这是与单账单流水零金额撤销事件的展示
337	// 差异，差异只发生在本筛选层。
338	func postbillRangeEvents(ops []postbillOp, startMonth, endMonth string, startSeq, endSeq int64) []reconEvent {
339		inRange := func(m string) bool { return m >= startMonth && m <= endMonth }
340		var out []reconEvent
341		for _, op := range ops {
342			if op.seq <= startSeq || op.seq > endSeq {
343				continue
344			}
345			var changes []reconMonthChange
346			for _, e := range op.effects {
347				if !inRange(e.month) {
348					continue
349				}
350				changes = append(changes, reconMonthChange{
351					month:         e.month,
352					deltaPayable:  e.deltaPayable,
353					deltaReceived: e.deltaReceived,
354					alloc:         e.alloc,
355					beforeAlloc:   e.beforeAlloc,
356					afterAlloc:    e.afterAlloc,
357				})
358			}
359			if len(changes) == 0 {
360				continue
361			}
362			out = append(out, reconEvent{
363				seq: op.seq, kind: op.kind, refID: op.refID, note: op.note,
364				linkSeq: op.linkSeq, payTotal: op.payTotal, payID: op.payID,
365				changes: changes,
366			})
367		}
368		return out
369	}
370

