			continue
		}
		if strings.TrimSpace(note) == "" {
			problems = append(problems, fmt.Sprintf("第 %d 行：备注不能为空", line))
			continue
		}

		rows = append(rows, &parsedRemitRow{
			line:       line,
			customerID: custID,
			payID:      payID,
			total:      total,
			note:       note,
		})
	}
	return rows, problems
}

