	settleFixedCust(h, "acme", "100", map[string]string{
		"2026-09": "5", "2026-10": "3", "2026-11": "2",
	}) // 欠款 500/300/200
	// 三笔各 500：依次 09:500 → 10:300,11:200 → 11 无剩余，第三笔无欠款应整批拒绝。
	csv := remitCSVHeader +
