func TestRemitImportPersistsAcrossRestart(t *testing.T) {
	h := newHarness(t)
	settleTwoCustomers(h)
	f := h.writeRemitFile("r.csv", remitCSVHeader+
		"pay-01,acme,600,季度汇款\n"+
		"pay-02,globex,200,货款\n")
