	if !strings.Contains(out, "新增 0 笔，重复跳过 2 行") {
		t.Fatal(out)
	}
	s := loadState(t, h)
	if !s.Payments["pay-01"].Auto || !s.Payments["pay-02"].Auto {
		t.Fatal("自动登记身份应跨重启保持")
	}
	out = h.mustRun("bill", "show", "acme", "2026-10")
	if !strings.Contains(out, "实收：100 分") {
		t.Fatal(out)
	}
}

